-- Belloch (curso="BELLOCH"): 252 preguntas. Ejecutar en Supabase
-- (Dashboard -> SQL Editor -> New query -> Run).
--
-- Dos fuentes:
-- * 154 de las autoevaluaciones de final de capítulo del Manual de psicopatología de Belloch,
--   Sandín y Ramos, vol. II (4.ª ed.), con su tabla de "Respuestas correctas". Transcritas de
--   capturas del PDF escaneado. Fuera, por dudosas: la 2.5 (fila de respuestas ilegible), la 8.3
--   (la tabla da la d y solo puede ser la a), las 10 del cap. 12 y las 5 primeras del 17, que
--   preguntan por un caso clínico que no está.
-- * 98 preguntas de repaso de CEDE sobre el vol. I (3.ª ed., 2020), con su tabla de respuestas.
--   Fuera, por dudosas: Pensamiento 2 (dos opciones correctas) y Memoria 5 (la definición es la de
--   criptomnesia, que no está entre las opciones).
--
-- El libro no trae explicaciones: en explicacion va de dónde sale cada pregunta. Generado por un
-- script que valida cada fila (4 opciones distintas, correcta 0-3, sin repetidas, sin el "punto +
-- número suelto" de supabase-detectar-basura-preguntas.sql). Se puede volver a ejecutar sin duplicar
-- nada: cada fila solo entra si no hay ya una pregunta BELLOCH con el mismo enunciado y opciones.

insert into public.preguntas (curso, tema, pregunta, opciones, correcta, explicacion, inventada)
select v.curso, v.tema, v.pregunta, v.opciones::jsonb, v.correcta, v.explicacion, false
from (values
('BELLOCH', 'Ansiedad y trastornos emocionales', '¿Cuál de los siguientes conceptos define mejor la respuesta de miedo?', '["Respuesta anticipatoria ante un peligro futuro.", "Respuesta asociada a la vía nerviosa «ojo-tálamo-amígdala».", "Reacción de preocupación ansiosa.", "Reacción asociada primariamente a tensión muscular y vigilancia."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 1, autoevaluación, pregunta 1.'),
('BELLOCH', 'Ansiedad y trastornos emocionales', 'El DSM-III se destacó, entre otras cosas, por caracterizar ciertos trastornos de ansiedad por primera vez en un sistema de clasificación de los trastornos mentales. Indique cuál de los siguientes trastornos, que se clasifica actualmente como trastorno de ansiedad (DSM-5), se definió por primera vez en el DSM-III:', '["Trastorno de estrés postraumático.", "Trastorno obsesivo-compulsivo.", "Trastorno de pánico.", "Neurosis fóbicas."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 1, autoevaluación, pregunta 2.'),
('BELLOCH', 'Ansiedad y trastornos emocionales', 'Entre los siguientes trastornos hay uno que aparece con mucha frecuencia como trastorno comórbido (no como diagnóstico principal) a otros trastornos emocionales. Indique de qué trastorno se trata:', '["Trastorno de ansiedad generalizada.", "Trastorno obsesivo-compulsivo.", "Fobia específica.", "Agorafobia."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 1, autoevaluación, pregunta 3.'),
('BELLOCH', 'Ansiedad y trastornos emocionales', '¿A qué constructo transdiagnóstico corresponde preferentemente la siguiente descripción: «Me siento irritable o con mal humor»?', '["Ansiedad.", "Sensibilidad a la ansiedad.", "Intolerancia al estrés.", "Afecto negativo."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 1, autoevaluación, pregunta 4.'),
('BELLOCH', 'Ansiedad y trastornos emocionales', 'De acuerdo con el modelo tripartito de Clark y Watson (1991), ¿qué aspecto diferencia la depresión de la ansiedad, siendo más característico de la primera?', '["El bajo afecto positivo.", "El nivel elevado de neuroticismo.", "La elevada sensibilidad al asco.", "El nivel elevado de activación fisiológica."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 1, autoevaluación, pregunta 5.'),
('BELLOCH', 'Ansiedad y trastornos emocionales', '¿A qué constructo transdiagnóstico corresponde preferentemente la siguiente descripción: «Me asusto cuando mi corazón late rápidamente»?', '["Sensibilidad a la ansiedad.", "Intolerancia a la incertidumbre.", "Intolerancia al estrés.", "Aceptación/conciencia."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 1, autoevaluación, pregunta 6.'),
('BELLOCH', 'Ansiedad y trastornos emocionales', 'Indique cuál de los siguientes trastornos se ha relacionado en mayor grado con la sensibilidad al asco:', '["Trastorno de ansiedad social.", "Trastorno de ansiedad generalizada.", "Fobias a la sangre-inyección-daño.", "Trastorno de pánico."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 1, autoevaluación, pregunta 7.'),
('BELLOCH', 'Ansiedad y trastornos emocionales', 'Según el modelo transdiagnóstico jerárquico de los trastornos emocionales, ¿cuál de los siguientes conceptos ocupa una posición más general o superior en la jerarquía?', '["Un trastorno mental (síndrome clínico).", "La preocupación.", "El perfeccionismo.", "La evitación exteroceptiva."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 1, autoevaluación, pregunta 8.'),
('BELLOCH', 'Ansiedad y trastornos emocionales', 'La conducta de inhibición conductual en el niño se asocia fundamentalmente a experiencias tempranas de:', '["Apego inseguro.", "Sobreprotección de los padres.", "Experiencias de permisividad de los padres.", "Experiencias de aprendizaje vicario."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 1, autoevaluación, pregunta 9.'),
('BELLOCH', 'Ansiedad y trastornos emocionales', 'En la descripción que hizo S. Freud sobre la psicopatología de las neurosis, este autor estableció:', '["Una dimensión de gravedad, situándose la ansiedad en el extremo de menor gravedad y la depresión en el de mayor gravedad.", "Un continuo de gravedad, situándose las neurosis en el extremo de menor gravedad y las psicosis en el de mayor gravedad.", "Dos dimensiones separadas, una referida a las neurosis y otra referida a las psicosis.", "Dos categorías separadas, una referida a las neurosis y otra referida a las psicosis."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 1, autoevaluación, pregunta 10.'),
('BELLOCH', 'Trastornos de ansiedad', 'Westphal definió en 1871 la agorafobia como:', '["Miedo a los lugares públicos.", "Miedo a los espacios abiertos.", "Miedo a los síntomas similares a los del ataque de pánico.", "Miedo a los lugares cerrados."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 2, autoevaluación, pregunta 1.'),
('BELLOCH', 'Trastornos de ansiedad', 'Indique cuál de los siguientes síntomas NO corresponde al conjunto de 13 síntomas a partir de los cuales se define el ataque de pánico (DSM-5):', '["Miedo a morir.", "Sensación de atragantarse.", "Sensación de asfixia.", "Irritabilidad o tensión muscular."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 2, autoevaluación, pregunta 2.'),
('BELLOCH', 'Trastornos de ansiedad', 'Partiendo de los datos que nos proporcionan los estudios epidemiológicos, señale cuál de las siguientes fobias específicas posee la mayor tasa de prevalencia:', '["Fobia a las alturas.", "Fobia a los espacios cerrados.", "Fobia a viajar en avión.", "Fobia a las tormentas."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 2, autoevaluación, pregunta 3.'),
('BELLOCH', 'Trastornos de ansiedad', 'Klein (1964, 1981) llevó a cabo varias aportaciones que mejoraron el conocimiento psicopatológico del trastorno de pánico. Indique cuál de las siguientes aportaciones NO corresponde a Klein:', '["Establecer que la agorafobia es una consecuencia de los ataques de pánico.", "Diferenciar entre ataque de pánico y ataque de ansiedad.", "Considerar el ataque de pánico como una neurosis de ansiedad.", "Establecer que, tras la experiencia de ataques de pánico, se desarrolla ansiedad anticipatoria hacia nuevos ataques."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 2, autoevaluación, pregunta 4.'),
('BELLOCH', 'Trastornos de ansiedad', 'El diagnóstico del trastorno de ansiedad generalizada requiere que, junto a la ansiedad y la preocupación, el individuo haya experimentado al menos tres síntomas de un conjunto de seis. Indique cuál de los siguientes síntomas NO se incluye para dicho diagnóstico (DSM-5):', '["Dificultad para concentrarse.", "Temblor muscular.", "Tener la mente «en blanco».", "Dificultades para dormir."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 2, autoevaluación, pregunta 6.'),
('BELLOCH', 'Trastornos de ansiedad', '¿Cuál de los siguientes modelos sobre la etiología del trastorno de ansiedad generalizada diferencia entre dos tipos de preocupaciones (preocupaciones Tipo 1 y preocupaciones Tipo 2)?', '["Modelo de aprensión ansiosa.", "Modelo de intolerancia a la incertidumbre.", "Modelo de evitación emocional basado en la preocupación.", "Modelo metacognitivo."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 2, autoevaluación, pregunta 7.'),
('BELLOCH', 'Trastornos de ansiedad', 'Aunque los trastornos de ansiedad son los trastornos más prevalentes entre todos los trastornos mentales, no todos tienen similares tasas de prevalencia. Entre los trastornos que se indican a continuación, ¿cuál tiene la tasa más baja de prevalencia?', '["Mutismo selectivo.", "Trastorno de pánico.", "Trastorno de ansiedad de separación.", "Trastorno de ansiedad generalizada."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 2, autoevaluación, pregunta 8.'),
('BELLOCH', 'Trastornos de ansiedad', 'En la etiología del trastorno de ansiedad de separación intervienen diversos factores familiares que también suelen asociarse a otros trastornos de ansiedad. No obstante, se ha sugerido (Wood, 2006) como factor específico de este trastorno:', '["El abuso sexual durante la infancia.", "El estilo de apego inseguro y miedoso/preocupado.", "La práctica de crianza permisiva.", "La práctica de crianza intrusiva."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 2, autoevaluación, pregunta 9.'),
('BELLOCH', 'Trastornos de ansiedad', 'El mutismo selectivo suele presentar elevada comorbilidad con otros trastornos de ansiedad, pero especialmente con:', '["El trastorno de ansiedad social.", "La fobia específica.", "La agorafobia.", "El trastorno de ansiedad generalizada."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 2, autoevaluación, pregunta 10.'),
('BELLOCH', 'Trastorno de ansiedad social', 'El trastorno de ansiedad social (TAS) se caracteriza por:', '["Miedo a la evaluación negativa.", "Miedo a comer delante de otros.", "Un marcado pesimismo sobre el futuro.", "Miedo a la evaluación en general."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 3, autoevaluación, pregunta 1.'),
('BELLOCH', 'Trastorno de ansiedad social', 'La principal diferencia entre el TAS y el trastorno de personalidad por evitación (TPE) es:', '["En el TPE la conducta de evitación es más general y constituye una forma global de organización de la experiencia.", "El TPE es una forma grave de TAS, pero la interferencia es menor.", "En el AS/TAS la conducta de evitación es más general y constituye una forma global de organización de la experiencia.", "No existen diferencias entre el TAS y el TPE."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 3, autoevaluación, pregunta 2.'),
('BELLOCH', 'Trastorno de ansiedad social', 'Desde la perspectiva evolucionista, la ansiedad social se entiende como:', '["Una respuesta adaptativa para responder a las amenazas a las que estamos expuestos como especie.", "Una respuesta exacerbada que se produce como consecuencia del miedo a la evaluación negativa.", "Una anticipación patológica a situaciones de interacción social.", "Una respuesta desadaptativa para responder a las amenazas a las que estamos expuestos como especie."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 3, autoevaluación, pregunta 3.'),
('BELLOCH', 'Trastorno de ansiedad social', 'El modo agónico es:', '["Una forma de funcionamiento que permite a los subordinados del grupo mostrarse superiores y dominar a los congéneres.", "Una forma de funcionamiento que permite a los subordinados del grupo reconocer y anticipar amenazas para poder reaccionar de inmediato dando muestras de sumisión y apaciguamiento que harán que el dominante abandone las amenazas y la posibilidad de infligir daño.", "Una forma de funcionamiento que ponen en marcha los dominantes del grupo ante la amenaza de algún subordinado.", "Una forma de funcionamiento típica del sistema de defensa, un logro evolutivo que permite derrotar al resto de los congéneres."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 3, autoevaluación, pregunta 4.'),
('BELLOCH', 'Trastorno de ansiedad social', '¿Cuál de los siguientes enunciados es falso respecto a las variaciones incluidas en el DSM-5 para el diagnóstico del TAS?', '["Se plantea el cambio de nombre de fobia social a trastorno de ansiedad social.", "Se genera un criterio específico para el miedo a la evaluación negativa.", "Se elimina el anterior especificador de fobia social generalizada.", "Se rechaza la necesidad de que el TAS haya estado presente durante, al menos, seis meses."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 3, autoevaluación, pregunta 5.'),
('BELLOCH', 'Trastorno de ansiedad social', '¿Qué comparte el TAS con la depresión y la ansiedad generalizada, pero no con el resto de trastornos de ansiedad?', '["El alto nivel de afecto negativo.", "El tipo de estrategia disfuncional para regular las emociones positivas.", "El bajo nivel de afecto positivo.", "El pensamiento perseverante ante la activación del circuito del miedo."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 3, autoevaluación, pregunta 6.'),
('BELLOCH', 'Trastorno de ansiedad social', 'Las conductas de seguridad permiten:', '["Reducir la ansiedad a largo plazo, pero la intensifican a corto plazo.", "Afrontar de manera satisfactoria las situaciones temidas.", "Reducir la ansiedad a corto plazo, pero la intensifican a largo plazo.", "Reducir la ansiedad, tanto a corto como a largo plazo."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 3, autoevaluación, pregunta 7.'),
('BELLOCH', 'Trastorno de ansiedad social', '¿Cuál de los siguientes enunciados caracteriza mejor a las personas con TAS?', '["Las personas con TAS siempre regulan las emociones y los pensamientos de manera desadaptativa.", "Las personas con TAS suelen tener miedo a la evaluación negativa, pero se sienten cómodas con la evaluación positiva.", "Las personas con TAS suelen tener imágenes mentales sobre eventos negativos del pasado, lo cual activa y mantiene la representación negativa del self.", "Las personas con TAS poseen niveles de interferencia muy elevados y el miedo, la ansiedad o la evitación se dan de forma generalizada en muchos ámbitos."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 3, autoevaluación, pregunta 8.'),
('BELLOCH', 'Trastorno de ansiedad social', '¿Qué modelo estipula que la atención se focaliza en la amenaza tanto interna como externa?', '["Rapee y Heimberg, 1997.", "Trower y Gilbert, 1989.", "Clark y Wells, 1995.", "Barlow y Hofmann, 2002."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 3, autoevaluación, pregunta 9.'),
('BELLOCH', 'Trastorno de ansiedad social', '¿Sobre qué aspecto(s) se considera necesario prestar atención en el tratamiento de la AS/TAS?', '["La evitación a las situaciones sociales.", "El criterio que la persona cree que utilizará la audiencia para juzgar su ejecución, así como el criterio que ella desea alcanzar.", "La auto-imagen negativa acerca del self.", "Todas las alternativas son correctas."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 3, autoevaluación, pregunta 10.'),
('BELLOCH', 'Trastorno de ansiedad social', '¿Qué afirmación es falsa acerca del miedo a la evaluación positiva en la AS/TAS?', '["Cuando la persona tiene éxito, teme no repetirlo en una tarea futura.", "Es un mecanismo evolutivo que alerta a la persona de posibles conflictos por su aumento de estatus o consideración por parte del resto.", "La evidencia indica que el miedo a la evaluación positiva correlaciona muy fuerte con la evaluación negativa y, por ello, se trata de un único factor.", "Existen escalas desarrolladas para medir específicamente el miedo a la evaluación positiva."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 3, autoevaluación, pregunta 11.'),
('BELLOCH', 'Trastornos relacionados con traumas y factores de estrés', 'Cuando los síntomas de estrés tras un acontecimiento traumático se diagnostican entre el tercer día y las primeras cuatro semanas después del suceso, se habla específicamente de un:', '["Trastorno de estrés agudo.", "Trastorno de estrés postraumático agudo.", "Trastorno adaptativo ansioso.", "Trastorno explosivo intermitente."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 4, autoevaluación, pregunta 1.'),
('BELLOCH', 'Trastornos relacionados con traumas y factores de estrés', '¿Cuáles son los núcleos sintomáticos centrales del trastorno de estrés postraumático en las personas adultas según el DSM-5?', '["Reexperimentación, evitación e hiperactivación.", "Hiperactivación, embotamiento afectivo, disociación y rituales cognitivos.", "Reexperimentación, evitación, hiperactivación y alteraciones cognitivas/cambios en el estado de ánimo.", "Reexperimentación, evitación conductual, evitación cognitiva e hiperactivación."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 4, autoevaluación, pregunta 2.'),
('BELLOCH', 'Trastornos relacionados con traumas y factores de estrés', 'En el trastorno de estrés postraumático los flashbacks están asociados a las conductas de:', '["Reexperimentación.", "Evitación conductual.", "Evitación cognitiva.", "Hiperactivación."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 4, autoevaluación, pregunta 3.'),
('BELLOCH', 'Trastornos relacionados con traumas y factores de estrés', 'Señala, entre los propuestos, un síntoma negativo del trastorno de estrés postraumático:', '["Reexperimentación del suceso.", "Evitación conductual y cognitiva de los estímulos asociados al suceso.", "Aumento de la activación psicofisiológica.", "Embotamiento afectivo."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 4, autoevaluación, pregunta 4.'),
('BELLOCH', 'Trastornos relacionados con traumas y factores de estrés', 'En el trastorno de estrés postraumático de inicio diferido (o con expresión retardada) el período transcurrido entre el suceso traumático y el comienzo de los síntomas es, al menos, de:', '["Un mes.", "Tres meses.", "Seis meses.", "Doce meses."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 4, autoevaluación, pregunta 5.'),
('BELLOCH', 'Trastornos relacionados con traumas y factores de estrés', 'Según el DSM-5, se debe especificar si el TEPT viene acompañado de forma persistente de:', '["Síntomas ansiosos.", "Síntomas disociativos.", "Síntomas depresivos.", "Síntomas obsesivos."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 4, autoevaluación, pregunta 6.'),
('BELLOCH', 'Trastornos relacionados con traumas y factores de estrés', 'Las exposiciones cortas a las imágenes traumáticas, que suscitan una respuesta intensa de ansiedad y que llevan al sujeto a respuestas de escape conductual o cognitivo, encajan con el concepto de:', '["Sensibilización.", "Habituación.", "Flashback.", "Disociación."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 4, autoevaluación, pregunta 7.'),
('BELLOCH', 'Trastornos relacionados con traumas y factores de estrés', '¿Cuál es el modelo teórico que mejor explica la reexperimentación persistente del suceso traumático en el trastorno de estrés postraumático?', '["El condicionamiento clásico.", "El condicionamiento instrumental.", "El condicionamiento de orden superior.", "La teoría del procesamiento de la información."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 4, autoevaluación, pregunta 8.'),
('BELLOCH', 'Trastornos relacionados con traumas y factores de estrés', '¿A partir de qué edad se puede hacer el diagnóstico de trastorno de apego reactivo según el DSM-5?', '["Tres meses.", "Seis meses.", "Nueve meses.", "Doce meses."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 4, autoevaluación, pregunta 9.'),
('BELLOCH', 'Trastornos relacionados con traumas y factores de estrés', 'Según el DSM-5, el trastorno de relación social desinhibida se considera persistente cuando este cuadro clínico ha estado presente más de:', '["Seis meses.", "Doce meses.", "Dieciocho meses.", "Veinticuatro meses."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 4, autoevaluación, pregunta 10.'),
('BELLOCH', 'Trastornos obsesivo-compulsivos y trastornos relacionados', '¿Cuál de las siguientes características es necesaria para realizar un diagnóstico de TOC?', '["Experimentar preocupaciones constantes sobre posibles problemas futuros.", "Que la persona trate de ignorar, suprimir o neutralizar sus obsesiones, con algún pensamiento o acción.", "Que exista conciencia de enfermedad.", "Que exista alguna relación entre el contenido de las obsesiones y el tipo o modalidad de compulsión."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 5, autoevaluación, pregunta 1.'),
('BELLOCH', 'Trastornos obsesivo-compulsivos y trastornos relacionados', '¿Cuál de los trastornos que se enumeran presenta las mayores tasas de comorbilidad con el TOC?', '["Trastornos de la conducta alimentaria.", "Depresión mayor.", "Gilles de la Tourette.", "Esquizofrenia."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 5, autoevaluación, pregunta 2.'),
('BELLOCH', 'Trastornos obsesivo-compulsivos y trastornos relacionados', '«Si tengo estos pensamientos es que me estoy volviendo loco». ¿Con cuál de las creencias disfuncionales sobre los pensamientos se corresponde mejor esta afirmación, realizada por una persona con TOC?', '["Sobrestimar la importancia de los pensamientos.", "Fusión pensamiento-acción, tipo moral.", "Perfeccionismo.", "Necesidad de controlar el pensamiento."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 5, autoevaluación, pregunta 3.'),
('BELLOCH', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'Uno de los comportamientos más frecuentes y claves en el mantenimiento del TDC es:', '["Realizar ejercicio físico.", "Examinarse en el espejo.", "Hacer dieta.", "Consumir alcohol."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 5, autoevaluación, pregunta 4.'),
('BELLOCH', 'Trastornos obsesivo-compulsivos y trastornos relacionados', '¿Cuál de los siguientes modelos ha sido propuesto para la explicación del desarrollo y mantenimiento del TDC?', '["El modelo de F. Neziroglu.", "El modelo de P. Salkovskis.", "El modelo de S. Wilhelm.", "Las opciones a y c."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 5, autoevaluación, pregunta 5.'),
('BELLOCH', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'Uno de los aspectos en los que se centra el modelo de David Veale para explicar el desarrollo y mantenimiento del TDC es:', '["El papel del condicionamiento clásico.", "El papel de las reacciones disfuncionales.", "El papel de las imágenes mentales.", "Ninguna de las anteriores."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 5, autoevaluación, pregunta 6.'),
('BELLOCH', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'En la tricotilomanía, el comportamiento de arrancarse el cabello:', '["Siempre da lugar a una pérdida perceptible del mismo.", "Siempre da lugar a una pérdida del mismo, aunque esta puede no ser perceptible.", "Algunas veces da lugar a la pérdida del cabello y otras no.", "Se asocia a bajos niveles de interferencia."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 5, autoevaluación, pregunta 7.'),
('BELLOCH', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'Los modelos explicativos actuales sobre los comportamientos repetidos centrados en el cuerpo (p. ej., la excoriación) plantean que estos podrían tener la función de:', '["Evitar enfrentarse al malestar que generan las creencias disfuncionales sobre el propio cuerpo.", "Regular las emociones negativas, tanto aquellas que implican niveles elevados (p. ej., la ansiedad) como bajos (p. ej., el aburrimiento) de activación.", "Disminuir la ansiedad que genera mirarse ante el espejo y ver una imagen que no se ajusta a la deseada (p. ej., acné).", "No cumplen ninguna función, son el resultado de un componente básicamente hereditario."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 5, autoevaluación, pregunta 8.'),
('BELLOCH', 'Trastornos obsesivo-compulsivos y trastornos relacionados', '¿Cuál de estas alteraciones se caracteriza por una menor conciencia de enfermedad?', '["El trastorno obsesivo-compulsivo.", "La tricotilomanía.", "La excoriación.", "El trastorno de acumulación."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 5, autoevaluación, pregunta 9.'),
('BELLOCH', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'En el trastorno de acumulación, la adquisición excesiva:', '["Siempre se observa, y hace referencia a la compra de objetos por su valor artístico.", "Se observa con frecuencia, pudiendo ser objetos comprados, gratuitos, o robados.", "Es poco frecuente, y suele caracterizarse por acumular objetos robados.", "Siempre se observa, y suele caracterizarse por acumular objetos comprados."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 5, autoevaluación, pregunta 10.'),
('BELLOCH', 'Trastornos depresivos', 'Para poder hablar de un episodio depresivo mayor, el DSM-5 requiere la presencia durante un período de al menos dos semanas de cinco o más síntomas entre los cuales uno debe ser o bien estado de ánimo depresivo o bien:', '["Pensamientos recurrentes de muerte o ideación suicida.", "Disminución acusada del interés o de la capacidad para el placer.", "Ansiedad y preocupación excesivas sobre una amplia gama de acontecimientos.", "Dificultades para conciliar o mantener el sueño."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 6, autoevaluación, pregunta 1.'),
('BELLOCH', 'Trastornos depresivos', 'Los tres elementos clave de la teoría cognitiva de la depresión de Beck son:', '["Esquemas cognitivos depresógenos; errores cognitivos; pensamientos automáticos negativos sobre el yo, el mundo y el futuro.", "Errores cognitivos; pensamientos automáticos negativos sobre el yo, el mundo y el futuro; habilidades de solución de problemas sociales.", "Actitudes disfuncionales; esquemas cognitivos depresógenos; habilidades de afrontamiento.", "Rumiación cognitiva; errores cognitivos; tríada cognitiva negativa."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 6, autoevaluación, pregunta 2.'),
('BELLOCH', 'Trastornos depresivos', 'Una de las diferencias fundamentales entre el trastorno depresivo persistente (TDP) y el trastorno depresivo mayor (TDM) en el DSM-5 es que:', '["En el TDM, los síntomas producen malestar clínicamente significativo o deterioro laboral, social o en otras áreas importantes, mientras que en el TDP no es necesario que los síntomas produzcan ese malestar o ese deterioro.", "En el TDP se pueden producir episodios maníacos o hipomaníacos, pero no en el TDM.", "En el TDM pueden aparecer delirios y alucinaciones congruentes con el estado de ánimo, pero no en el TDP.", "Las tres alternativas anteriores son incorrectas."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 6, autoevaluación, pregunta 3.'),
('BELLOCH', 'Trastornos depresivos', 'El trastorno depresivo que en el DSM-IV se llamaba trastorno distímico, en el DSM-5 se incluye dentro del:', '["Trastorno depresivo persistente.", "Trastorno depresivo no especificado.", "Trastorno de distimia.", "Trastorno depresivo mayor."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 6, autoevaluación, pregunta 4.'),
('BELLOCH', 'Trastornos depresivos', 'En el DSM-5, la distinción entre trastorno depresivo mayor (TDM) y duelo se basaría en que si la persona presenta síntomas depresivos tras la muerte de un ser querido (siendo uno el estado de ánimo deprimido o la anhedonia), si tales síntomas:', '["Duran más de dos meses haríamos el diagnóstico de TDM, no de duelo.", "Son muy incapacitantes o incluyen síntomas muy graves (p. ej., suicidio), haríamos el diagnóstico de TDM, no de duelo.", "Duran más de un año, haríamos el diagnóstico de TDM, no de duelo.", "Incluyen insomnio y cansancio, haríamos el diagnóstico de TDM, no de duelo."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 6, autoevaluación, pregunta 5.'),
('BELLOCH', 'Trastornos depresivos', 'En el DSM-5 se distinguen al menos los siguientes trastornos depresivos:', '["Trastorno depresivo mayor, trastorno disfórico menstrual, trastorno depresivo breve y trastornos de desregulación disruptiva del estado de ánimo.", "Trastorno depresivo mayor, trastorno depresivo endógeno, trastorno depresivo persistente y trastorno disfórico menstrual.", "Trastorno depresivo mayor, trastorno de desregulación disruptiva del estado de ánimo, trastorno depresivo posparto y trastorno disfórico menstrual.", "Trastorno depresivo mayor, trastorno disfórico menstrual, trastorno depresivo persistente y trastornos de desregulación disruptiva del estado de ánimo."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 6, autoevaluación, pregunta 6.'),
('BELLOCH', 'Trastornos depresivos', 'Según el DSM-5, una de las características clave para el diagnóstico del trastorno depresivo persistente en adultos es que la persona:', '["Presenta un estado de ánimo crónicamente depresivo durante al menos cuatro años.", "Durante dos años no ha estado sin síntomas depresivos más de dos meses seguidos.", "Presenta síntomas depresivos en respuesta a un estresante identificable dentro de los tres meses siguientes a la presencia del estresante.", "Presenta un estado de ánimo crónicamente depresivo durante al menos un año."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 6, autoevaluación, pregunta 7.'),
('BELLOCH', 'Trastornos depresivos', 'Los datos actualmente disponibles sobre la eficacia de la terapia cognitiva para la depresión indican que:', '["La terapia cognitiva es igual de eficaz que la medicación antidepresiva en las depresiones leves y moderadas, pero es menos eficaz en las depresiones graves.", "La terapia cognitiva es más eficaz que la medicación antidepresiva tanto en las depresiones leves y moderadas como en las depresiones graves.", "La terapia cognitiva es igual de eficaz que la medicación antidepresiva tanto en las depresiones leves y moderadas como en las depresiones graves.", "La terapia cognitiva es igual de eficaz que la medicación antidepresiva en las depresiones leves, pero es menos eficaz en las depresiones moderadas o graves."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 6, autoevaluación, pregunta 8.'),
('BELLOCH', 'Trastornos depresivos', 'Según el DSM-5, uno de los síntomas clave para el diagnóstico del trastorno de desregulación disruptiva del estado de ánimo es la presencia, entre los accesos de cólera verbal y conductas agresivas, de:', '["Tristeza persistente.", "Anhedonia persistente.", "Irritabilidad persistente.", "Ansiedad persistente."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 6, autoevaluación, pregunta 9.'),
('BELLOCH', 'Trastornos depresivos', 'Ha pasado un mes desde el fallecimiento de su esposa, y Juan, su marido, presenta casi todos los días, la mayor parte de los días, sentimiento de pérdida o vacío, cansancio, insomnio y agitación psicomotora. Según el DSM-5, lo más probable es que Juan presente:', '["Trastorno depresivo mayor.", "Trastorno de duelo complicado.", "Trastorno depresivo breve.", "Duelo."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 6, autoevaluación, pregunta 10.'),
('BELLOCH', 'Trastorno bipolar y trastornos relacionados', 'El trastorno bipolar (señale la frase incorrecta):', '["Consiste en la aparición de episodios depresivos y de episodios maníacos e hipomaníacos.", "Con el tiempo los episodios se atenúan y tienden a desaparecer.", "Es una enfermedad mental grave asociada a altas tasas de discapacidad.", "El suicidio no es infrecuente, sobre todo en las fases depresivas."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 7, autoevaluación, pregunta 1.'),
('BELLOCH', 'Trastorno bipolar y trastornos relacionados', '¿Cuál es la principal causa del trastorno bipolar?', '["Factores genéticos.", "Abuso de sustancias.", "Antecedentes de maltrato.", "Antecedentes de factores estresantes."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 7, autoevaluación, pregunta 2.'),
('BELLOCH', 'Trastorno bipolar y trastornos relacionados', 'De las siguientes cifras, ¿cuál es la que más se acerca a la prevalencia del trastorno bipolar (incluyendo todos sus subtipos)?', '["0,5%.", "1%.", "2%.", "5%."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 7, autoevaluación, pregunta 3.'),
('BELLOCH', 'Trastorno bipolar y trastornos relacionados', 'Según la teoría de Beck, ¿cuál de las siguientes NO es una actitud disfuncional en la manía?', '["Si hay alguna posibilidad de éxito debería aceptar el riesgo, porque ganaré.", "Merezco más de lo que tengo.", "Mis recursos son ilimitados.", "Cuando la gente me mira, me desea lo peor."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 7, autoevaluación, pregunta 4.'),
('BELLOCH', 'Trastorno bipolar y trastornos relacionados', '¿Cuál de los siguientes NO es un síntoma anímico propio de la manía?', '["Euforia.", "Hiperactividad.", "Anhedonia.", "Insomnio."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 7, autoevaluación, pregunta 5.'),
('BELLOCH', 'Trastorno bipolar y trastornos relacionados', '¿Cuál de los siguientes NO es un delirio congruente con el estado de ánimo en la fase depresiva del TB?', '["Delirio de ruina.", "Delirio de aliñamiento.", "Delirio hipocondríaco.", "Delirio de culpa."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 7, autoevaluación, pregunta 6.'),
('BELLOCH', 'Trastorno bipolar y trastornos relacionados', '¿Cuál de las siguientes definiciones se adecua al trastorno bipolar tipo II?', '["La alternancia entre episodios depresivos y episodios maníacos.", "La aparición de sintomatología mixta en los episodios maníacos.", "La alternancia entre episodios depresivos y episodios hipomaníacos.", "La aparición de episodios maníacos tras el uso de antidepresivos."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 7, autoevaluación, pregunta 7.'),
('BELLOCH', 'Trastorno bipolar y trastornos relacionados', 'Según el DSM-5, ¿cuánto deben durar los síntomas para poder ser diagnosticado de un trastorno ciclotímico en el adulto?', '["Dos años.", "Un año.", "Seis meses.", "Tres meses."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 7, autoevaluación, pregunta 8.'),
('BELLOCH', 'Trastorno bipolar y trastornos relacionados', 'La psicoeducación en el trastorno bipolar:', '["Es el tratamiento de primera elección.", "Tiene eficacia demostrada para revertir un episodio agudo maníaco.", "Está indicada para mejorar la adherencia al tratamiento y prevenir futuras recaídas.", "No tiene indicación en el trastorno bipolar."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 7, autoevaluación, pregunta 9.'),
('BELLOCH', 'Trastorno bipolar y trastornos relacionados', 'Respecto al tratamiento farmacológico del TB, ¿cuál es la entidad que menos responde a los tratamientos disponibles en la actualidad?', '["Prevención de los episodios maníacos y depresivos.", "Tratamiento de la manía aguda.", "Tratamiento de los síntomas psicóticos.", "Tratamiento de la depresión bipolar."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 7, autoevaluación, pregunta 10.'),
('BELLOCH', 'Trastornos disociativos', 'Cuando hablamos de la conceptualización de los fenómenos disociativos podemos afirmar:', '["Que son fenómenos psicopatológicos graves que se dan en trastornos de personalidad y otros trastornos de ansiedad.", "Son fenómenos no necesariamente patológicos que, en ocasiones, podrían atenuar el impacto del estrés vivido y facilitar la adaptación y supervivencia.", "Que son fenómenos psicopatológicos graves que se dan en trastornos psicóticos exclusivamente.", "Son fenómenos que podrían atenuar el impacto del estrés vivido y facilitar la adaptación y supervivencia, pero siempre desde el punto de vista patológico."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 8, autoevaluación, pregunta 1.'),
('BELLOCH', 'Trastornos disociativos', 'Desde la teoría de la disociación estructural de Van der Hart (Van der Hart et al., 2006), se propone la disociación como un mecanismo de respuesta al trauma, que abarca:', '["Desde los cuadros somatoformes hasta los trastornos adaptativos.", "El trastorno por estrés postraumático (TEPT) y los trastornos de ansiedad en todas sus presentaciones clínicas.", "Desde el trastorno por estrés postraumático (TEPT) hasta los cuadros postraumáticos graves, estando el trastorno de identidad disociativo (TID o personalidad múltiple) en el extremo de este espectro postraumático.", "Desde el trastorno por estrés postraumático (TEPT) hasta los cuadros postraumáticos graves, pero excluyendo el trastorno de identidad disociativo (TID) del espectro postraumático."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 8, autoevaluación, pregunta 2.'),
('BELLOCH', 'Trastornos disociativos', 'Señala la afirmación correcta:', '["A la hora de abordar el trabajo terapéutico con los trastornos disociativos, independientemente de la orientación, es imprescindible un acceso temprano a los contenidos traumáticos para evitar descompensaciones de los pacientes.", "A la hora de abordar el tratamiento de los trastornos disociativos, hay que tener en cuenta su relación con el trauma, pero valorando que un acceso temprano a los contenidos traumáticos puede producir descompensaciones en la persona.", "En el abordaje terapéutico de los trastornos disociativos, la relación de estos con la historia traumática es poco frecuente, por lo que un trabajo centrado en la regulación emocional será suficiente.", "En el abordaje terapéutico de los trastornos disociativos, la relación de estos con la historia traumática es muy frecuente pero difícil de conceptualizar, por lo que se descarta abordarla en el proceso."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 8, autoevaluación, pregunta 4.'),
('BELLOCH', 'Trastornos disociativos', 'Señala la afirmación correcta:', '["Cuando nos encontramos con personas que han sufrido trauma complejo, la presencia de disociación suele ser muy destacada, surgiendo la necesidad de identificarla para trabajarla a nivel de psicoterapia.", "Cuando nos encontramos con personas que han sufrido trauma complejo, la presencia de disociación suele ser muy destacada, pero no se debe trabajar nunca a nivel psicoterapéutico con ella.", "Cuando nos encontramos con personas que han sufrido trauma complejo, la presencia de disociación suele ser poco frecuente, por lo que la evaluación de su historia de vida será sencilla.", "Cuando nos encontramos con personas que han sufrido trauma complejo, la presencia de disociación suele ser bastante frecuente, por lo que el establecimiento de su historia de vida no será indicado en ningún caso."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 8, autoevaluación, pregunta 5.'),
('BELLOCH', 'Trastornos disociativos', 'La despersonalización consiste en:', '["Una sensación de extrañeza del entorno y las personas conocidas, que pueden parecer no familiares.", "Una sensación de extrañeza, como si la persona fuera observada y controlada desde fuera, percibiendo intensas sensaciones en su cuerpo.", "Una mezcla de sensación de familiaridad y extrañeza respecto al entorno, las personas que rodean a la persona y a su propio cuerpo.", "Una sensación de extrañeza, como si la persona se observase funcionar «en automático», se viera desde fuera de sí misma, o como si estuviese alejada de sí misma o desconectada del cuerpo."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 8, autoevaluación, pregunta 6.'),
('BELLOCH', 'Trastornos disociativos', 'Los cinco ámbitos que han descrito Steinberg y Schnall (2000), presentes en la disociación, son:', '["Amnesia lacunar, despersonalización, hipersomnio, aplanamiento afectivo y alteración de la identidad.", "Desrealización, despersonalización, sentido de presencia, pseudoalucinaciones y activación desproporcionada del arousal.", "Amnesia, despersonalización, desrealización, confusión de identidad y alteración de identidad.", "Amnesia retrógrada, desrealización, insomnio, aplanamiento afectivo y alteración de la identidad."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 8, autoevaluación, pregunta 7.'),
('BELLOCH', 'Trastornos disociativos', 'Cuando decimos que las experiencias de trauma temprano están relacionadas con la etiología de los trastornos disociativos, nos referimos a:', '["Las experiencias que se producen en las relaciones de apego primarias, como el abuso de distintos tipos y la negligencia o falta de cuidados.", "Las experiencias transgeneracionales que están presentes en las pautas familiares y vínculos de la vida adulta.", "Las experiencias que se producen entre los iguales durante la infancia, especialmente en el contexto escolar.", "El consumo de sustancias tóxicas por parte de la figura materna durante la gestación."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 8, autoevaluación, pregunta 8.'),
('BELLOCH', 'Trastornos disociativos', 'En el modelo de la disociación estructural que nos proporciona el Dr. Onno Van der Hart, algunos postulados son:', '["Existe una parte emocional, distinta a la parte aparentemente normal, que es la que codifica y almacena la información sobre el trauma y lo revive a través de las emociones y las experiencias sensoriomotoras.", "Existe una parte emocional, distinta a la parte aparentemente normal, que evita física y mentalmente cualquier elemento relacionado con el trauma, intentando actuar como si no hubiera ocurrido.", "Tanto la parte aparentemente normal como la parte emocional de la personalidad evitan física y mentalmente cualquier elemento relacionado con el trauma, intentando actuar como si no hubiera ocurrido.", "Tanto la parte aparentemente normal como la parte emocional codifican y almacenan la información sobre el trauma y lo reviven a través de las emociones y las experiencias sensoriomotoras."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 8, autoevaluación, pregunta 9.'),
('BELLOCH', 'Trastornos disociativos', 'A nivel de los estudios de epidemiología de los trastornos disociativos, se puede afirmar:', '["Que los trastornos disociativos constituyen un problema de salud mental frecuente, no solo en la práctica clínica, sino también en la comunidad.", "Que los trastornos disociativos apenas tienen impacto en la población clínica, siendo muy rara su presencia.", "Que los trastornos disociativos son más frecuentes y prevalentes que los trastornos de ansiedad en la población normal.", "Todas las anteriores opciones son correctas."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 8, autoevaluación, pregunta 10.'),
('BELLOCH', 'Trastorno de síntomas somáticos y trastornos relacionados', 'El trastorno de síntomas somáticos se caracteriza por:', '["Pensamientos, sentimientos o comportamientos excesivos e inadaptados relacionados con sus síntomas somáticos.", "La preocupación por padecer o contraer una enfermedad grave.", "La ausencia de síntomas somáticos o, si están presentes, son únicamente leves.", "Un grado elevado de ansiedad acerca de la salud, y el individuo se alarma con facilidad por su estado de salud."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 9, autoevaluación, pregunta 1.'),
('BELLOCH', 'Trastorno de síntomas somáticos y trastornos relacionados', 'En el trastorno de ansiedad por la enfermedad:', '["Se experimentan uno o más síntomas somáticos que causan malestar o dan lugar a problemas significativos en la vida diaria.", "No existen síntomas somáticos o, si están presentes, son únicamente leves.", "Hay un tiempo y energía excesivos consagrados a los síntomas o a la preocupación por la salud.", "Existe un grado persistentemente elevado de ansiedad acerca de la salud o los síntomas."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 9, autoevaluación, pregunta 2.'),
('BELLOCH', 'Trastorno de síntomas somáticos y trastornos relacionados', 'En el trastorno de conversión:', '["Se experimentan pensamientos desproporcionados sobre la gravedad de los síntomas, y a menudo se consideran amenazadores.", "La persona produce intencionalmente signos o síntomas físicos o psicológicos.", "Se enfatiza la importancia de los datos clínicos y el examen neurológico.", "Las personas con el trastorno realizan conductas excesivas asociadas a la salud."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 9, autoevaluación, pregunta 3.'),
('BELLOCH', 'Trastorno de síntomas somáticos y trastornos relacionados', 'En los factores psicológicos que influyen en otras afecciones médicas:', '["El objetivo de la persona es obtener y mantener los beneficios que el adoptar el rol de enfermo pueda proporcionar.", "Implica un patrón en el que los síntomas o los déficits que afectan a los sentidos o al comportamiento motor sugieren que el paciente tiene una condición médica o neurológica.", "Puede aplicarse en individuos que sufren una condición médica que se ve afectada negativamente por factores psicológicos o conductuales.", "Existen síntomas somáticos que causan malestar y deterioro de las actividades de la vida diaria."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 9, autoevaluación, pregunta 4.'),
('BELLOCH', 'Trastorno de síntomas somáticos y trastornos relacionados', 'El trastorno facticio se diferencia de la simulación en que:', '["Los signos o síntomas físicos o psicológicos de la enfermedad se producen intencionadamente para obtener ganancias secundarias (p. ej., una compensación económica).", "No existen síntomas somáticos o, si están presentes, son únicamente leves.", "Implica múltiples síntomas corporales que pueden variar con el tiempo.", "Los signos o síntomas físicos o psicológicos de la enfermedad se producen intencionadamente para asumir el rol de enfermo."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 9, autoevaluación, pregunta 5.'),
('BELLOCH', 'Trastorno de síntomas somáticos y trastornos relacionados', 'La disforia por integridad corporal:', '["Implica síntomas corporales que son angustiantes para el individuo y a los que se dirige una atención excesiva.", "Implica una perturbación en la experiencia de la persona con respecto al cuerpo, que se manifiesta a través del deseo persistente de tener una discapacidad física específica.", "El individuo debe presentarse como enfermo y el diagnóstico depende de la identificación de que el individuo está tergiversando activamente su enfermedad.", "Puede aplicarse en individuos que sufren una condición médica que se ve afectada negativamente por factores psicológicos o conductuales."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 9, autoevaluación, pregunta 6.'),
('BELLOCH', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Uno de los aspectos que caracteriza al trastorno de síntomas somáticos es:', '["La preocupación por llegar a padecer dolor.", "Experimentar diversos síntomas somáticos junto con pensamientos y preocupaciones sobre su gravedad.", "Déficits que afectan las funciones motoras voluntarias o sensoriales, y que sugieren una enfermedad neurológica o médica.", "Miedo a tener una enfermedad grave ante la más leve molestia física."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 9, autoevaluación, pregunta 7.'),
('BELLOCH', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Según la propuesta cognitivo-conductual de Warwick y Salkovskis, las interpretaciones erróneas sobre los síntomas corporales que realizan las personas hipocondríacas tienen su origen en:', '["Experiencias infantiles de exposición a modelos que exhiben quejas físicas fingidas.", "Experiencias previas negativas relacionadas con la enfermedad (propias o de otras personas) que conducen a la formación de actitudes disfuncionales sobre la salud y la enfermedad.", "La movilización de impulsos primarios a modo de síntomas físicos que sirven como defensa cuando la autoestima se ve amenazada.", "La toma de conciencia por parte de la persona de las ventajas que comporta adoptar el papel de enfermo."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 9, autoevaluación, pregunta 8.'),
('BELLOCH', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Cuando una persona busca asumir el papel de enfermo, y finge o produce intencionadamente signos o síntomas físicos o psicológicos sin que haya incentivos externos para ello, nos encontramos ante:', '["Simulación.", "Trastorno facticio.", "Trastorno de conversión.", "Trastorno límite de la personalidad."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 9, autoevaluación, pregunta 9.'),
('BELLOCH', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Según Warwick y Salkovskis, la hipocondría puede ser considerada como análoga a un trastorno de:', '["Ansiedad por la salud.", "Ansiedad por la enfermedad.", "Amplificación somato-sensorial.", "Personalidad."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 9, autoevaluación, pregunta 10.'),
('BELLOCH', 'Trastornos de adaptación', 'Los trastornos de adaptación (señale la alternativa incorrecta):', '["Suelen ser una categoría diagnóstica frecuentemente utilizada en la práctica clínica.", "Se desarrollan siempre en respuesta a uno o más acontecimientos estresantes.", "Implican la aparición de amnesia disociativa respecto a algunos acontecimientos estresantes.", "Una vez finalizada la situación de estrés o sus consecuencias, los síntomas no se mantienen durante más de seis meses."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 10, autoevaluación, pregunta 1.'),
('BELLOCH', 'Trastornos de adaptación', 'Una de las diferencias existentes entre el DSM-5 y la CIE-11 a la hora de describir las características de los trastornos de adaptación es que la CIE-11:', '["Establece más subtipos dentro de esta categoría diagnóstica.", "No requiere la presencia de un deterioro significativo en las distintas áreas de funcionamiento de la persona.", "Considera que los síntomas pueden aparecer de forma retardada al suceso estresante (hasta un año después del mismo).", "Establece como característica esencial de este trastorno la presencia de preocupación excesiva por el acontecimiento estresante o sus consecuencias."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 10, autoevaluación, pregunta 2.'),
('BELLOCH', 'Trastornos de adaptación', 'Entre los subtipos de trastornos adaptativos especificados en el DSM-5 se encuentran (señale la alternativa incorrecta):', '["Con estado de ánimo depresivo.", "Con síntomas de estrés agudo.", "Con ansiedad.", "Con alteraciones de conducta."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 10, autoevaluación, pregunta 3.'),
('BELLOCH', 'Trastornos de adaptación', 'Entre los principales problemas que se presentan a la hora de diagnosticar un trastorno de adaptación se encuentran:', '["Su diferenciación de las respuestas normales al estrés.", "La falta de evidencia empírica para los subtipos.", "Su solapamiento con las presentaciones subclínicas de otros trastornos.", "Todas las alternativas anteriores son correctas."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 10, autoevaluación, pregunta 4.'),
('BELLOCH', 'Trastornos de adaptación', 'Entre los síntomas que pueden estar presentes en los trastornos de adaptación se encuentran (señale la alternativa incorrecta):', '["Distorsiones perceptivas.", "Sentimientos de inquietud.", "La ideación y conductas suicidas.", "Bajo estado de ánimo."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 10, autoevaluación, pregunta 5.'),
('BELLOCH', 'Trastornos de adaptación', 'El modelo del grupo de trabajo de Maercker y cols. (2007) sobre la etiología de los trastornos de adaptación parte o se fundamenta en las teorías explicativas ya establecidas para:', '["La depresión.", "El trastorno de estrés postraumático.", "El trastorno de ansiedad generalizada.", "Los trastornos disociativos."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 10, autoevaluación, pregunta 6.'),
('BELLOCH', 'Trastornos de adaptación', 'Entre las directrices generales de los tratamientos psicológicos para los trastornos de adaptación se encuentran (señale la alternativa incorrecta):', '["Reducir el impacto del factor estresante.", "Mejorar las capacidades de afrontamiento.", "La eliminación de los síntomas específicos que presente la persona.", "Confrontar a la persona con la realidad para mejorar sus déficits perceptivos."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 10, autoevaluación, pregunta 7.'),
('BELLOCH', 'Trastornos de adaptación', 'Actualmente, la evidencia empírica existente sobre la eficacia de los programas de tratamiento para los trastornos de adaptación oscila entre:', '["Baja o muy baja tanto para los tratamientos farmacológicos como psicológicos.", "Moderada para los tratamientos psicológicos y baja para los farmacológicos.", "Moderada para los tratamientos farmacológicos y baja para los psicológicos.", "Moderada tanto para los tratamientos psicológicos como farmacológicos."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 10, autoevaluación, pregunta 8.'),
('BELLOCH', 'Trastornos de adaptación', '¿Cuál de los siguientes factores de riesgo que predisponen al desarrollo de los trastornos de adaptación aparece exclusivamente asociado a estos trastornos?', '["Alto neuroticismo.", "Un patrón de crianza caracterizado por una sobreprotección paternal.", "La alexitimia.", "Ninguna de las anteriores es correcta."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 10, autoevaluación, pregunta 9.'),
('BELLOCH', 'Trastornos de adaptación', '¿Cuál de las siguientes afirmaciones sobre la evaluación de los trastornos de adaptación es correcta?', '["Es recomendable evaluarlos una vez finalice la situación o factor estresante para valorar de manera más precisa las secuelas que ha provocado en la persona.", "Es recomendable evaluarlos solo a través de cuestionarios de autoinforme ya que, durante la entrevista clínica, la persona suele mostrarse retraída y esquiva.", "Su evaluación no está incluida de forma apropiada en las principales entrevistas diagnósticas de uso frecuente en la práctica clínica.", "Es muy difícil su evaluación debido al estado de desorientación que presenta la persona durante el trastorno."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 10, autoevaluación, pregunta 10.'),
('BELLOCH', 'Espectro de la esquizofrenia y otros trastornos psicóticos', 'Desde el punto de vista del diagnóstico, la presencia de deterioro cognitivo es más probable:', '["En la esquizofrenia.", "En el trastorno esquizoafectivo.", "En el trastorno bipolar.", "En el trastorno psicótico breve."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 11, autoevaluación, pregunta 1.'),
('BELLOCH', 'Espectro de la esquizofrenia y otros trastornos psicóticos', 'Desde el punto de vista del diagnóstico, la presencia de síntomas negativos es más probable:', '["En el trastorno esquizoafectivo.", "En el trastorno delirante.", "En la esquizofrenia.", "En el trastorno esquizofreniforme."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 11, autoevaluación, pregunta 2.'),
('BELLOCH', 'Espectro de la esquizofrenia y otros trastornos psicóticos', 'Con respecto a los síntomas negativos es cierto que:', '["Tienen mayor fiabilidad interjueces que los síntomas psicomotores.", "Los síntomas negativos secundarios son inherentes a la esquizofrenia.", "El síndrome deficitario es la presencia de síntomas negativos primarios durante al menos un año.", "La alogia es evaluada de manera más fidedigna por medio de técnicas de autoinforme."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 11, autoevaluación, pregunta 3.'),
('BELLOCH', 'Espectro de la esquizofrenia y otros trastornos psicóticos', 'La relación entre los síntomas depresivos y los negativos es:', '["Los síntomas depresivos agravan los negativos.", "Los síntomas negativos producen y agravan los depresivos.", "Los síntomas negativos se caracterizan por cogniciones de culpa y desesperanza.", "Son los síntomas depresivos los que se relacionan con el deterioro cognitivo."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 11, autoevaluación, pregunta 4.'),
('BELLOCH', 'Espectro de la esquizofrenia y otros trastornos psicóticos', 'Respecto del diagnóstico de trastorno delirante:', '["Domina un cuadro alucinatorio.", "Pueden darse ideas delirantes bizarras.", "Se caracteriza por la presencia de deterioro cognitivo.", "Domina la dimensión desorganizada."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 11, autoevaluación, pregunta 5.'),
('BELLOCH', 'Espectro de la esquizofrenia y otros trastornos psicóticos', 'Una de las siguientes características identifica un estado mental de alto riesgo:', '["Síndrome deficitario.", "Síndrome catatónico.", "Síntomas psicóticos atenuados o breves si están presentes.", "Síntomas de habla desorganizada presente en el último año."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 11, autoevaluación, pregunta 6.'),
('BELLOCH', 'Espectro de la esquizofrenia y otros trastornos psicóticos', 'La presencia de deterioro cognitivo está relacionada con:', '["La dimensión psicótica.", "La dimensión desorganizada.", "La dimensión afectiva.", "El trastorno psicótico breve."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 11, autoevaluación, pregunta 7.'),
('BELLOCH', 'Espectro de la esquizofrenia y otros trastornos psicóticos', 'Las llamadas alteraciones del self parecen centrales:', '["En el trastorno delirante.", "En el espectro de la esquizofrenia.", "En la fase residual de la esquizofrenia.", "En el trastorno psicótico compartido."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 11, autoevaluación, pregunta 8.'),
('BELLOCH', 'Espectro de la esquizofrenia y otros trastornos psicóticos', 'Un indicador de mal pronóstico sería:', '["Un delirio de inicio agudo.", "Experiencias psicóticas vividas con perplejidad y confusión.", "Estado de ánimo depresivo.", "Aplanamiento afectivo."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 11, autoevaluación, pregunta 9.'),
('BELLOCH', 'Espectro de la esquizofrenia y otros trastornos psicóticos', 'En uno de los siguientes trastornos es improbable encontrar la dimensión desorganizada:', '["Trastorno esquizoafectivo.", "Esquizofrenia.", "Trastorno esquizofreniforme.", "Trastorno delirante."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 11, autoevaluación, pregunta 10.'),
('BELLOCH', 'Trastornos de la personalidad', '¿Cuál de las siguientes características diferencia los TP de otros trastornos mentales?', '["Al igual que todos los trastornos mentales, los TP presentan un repertorio de comportamientos limitado, reiterativo, e inflexible, que cambia relativamente poco en función de las demandas y situaciones.", "Los TP afectan parcialmente al individuo y los diferentes ámbitos de su funcionamiento, a diferencia de lo que suele suceder con la mayoría de los trastornos mentales.", "Los TP son generalmente egosintónicos, a diferencia de la egodistonía que caracteriza a la mayoría de los trastornos mentales.", "La diferenciación entre los TP y otros trastornos mentales es más bien difusa, ya que comparten síntomas comunes."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 13, autoevaluación, pregunta 1.'),
('BELLOCH', 'Trastornos de la personalidad', 'Uno de los cambios importantes de la quinta edición del DSM en relación con los TP es:', '["Su inclusión en un eje diferente al del retraso mental.", "La desaparición del trastorno esquizotípico del grupo de los TP.", "La inclusión de un patrón límite, en sustitución del trastorno de la personalidad límite.", "La desaparición de un eje diagnóstico específico para los TP."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 13, autoevaluación, pregunta 2.'),
('BELLOCH', 'Trastornos de la personalidad', 'Los estudios sobre prevalencia de los TP coinciden en señalar que:', '["La prevalencia ha aumentado considerablemente en la última década.", "La prevalencia se mantiene estable en función de variables como el contexto social, el cultural, o el educativo.", "La prevalencia aumenta cuando se producen situaciones sociales de conflicto y violencia, como sucede con el resto de los trastornos mentales.", "El trastorno de la personalidad narcisista se encuentra entre los más prevalentes, independientemente del contexto social o cultural."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 13, autoevaluación, pregunta 3.'),
('BELLOCH', 'Trastornos de la personalidad', 'Según el modelo alternativo del DSM-5, una persona presentaría un TP si cumpliera los siguientes criterios:', '["Dificultades, de gravedad igual o mayor a leve, en el funcionamiento de la personalidad (auto/interpersonal) y uno o más rasgos patológicos de personalidad.", "Dificultad, entre moderada y grave, en el funcionamiento de la personalidad (auto/interpersonal) y uno o más rasgos patológicos de personalidad.", "Dificultades en el funcionamiento de la personalidad y rasgos patológicos de personalidad relativamente cambiantes a lo largo del ciclo vital del individuo.", "Dificultades en el funcionamiento de la personalidad y rasgos patológicos de personalidad que se corresponden con la etapa de desarrollo evolutivo de la persona."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 13, autoevaluación, pregunta 4.'),
('BELLOCH', 'Trastornos de la personalidad', 'Los rasgos patológicos de personalidad según el modelo alternativo del DSM-5 son:', '["Afectividad negativa, desapego, anti-sociabilidad, desinhibición, y anancastia.", "Identidad, empatía, autodirección e intimidad.", "Afecto negativo, desapego, antagonismo, desinhibición y psicoticismo.", "Búsqueda de novedades, evitación del daño y dependencia de la recompensa."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 13, autoevaluación, pregunta 5.'),
('BELLOCH', 'Trastornos de la personalidad', 'Una persona cumple los criterios A y B para el diagnóstico de TP, pero no presenta los criterios aplicables para ningún TP concreto. Según las recomendaciones de Skodol (2015), lo que deberíamos hacer para determinar el diagnóstico, según el modelo alternativo del DSM-5, es:', '["Aplicar criterios de inclusión y exclusión (D, E, F, G).", "Aplicar los criterios A y B al TP-especificado por rasgos.", "Confirmar el diagnóstico de TP sobre la base de que se cumplen los criterios A y B.", "Determinar el TP entre los tipos propuestos y/o realizar un diagnóstico categorial."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 13, autoevaluación, pregunta 6.'),
('BELLOCH', 'Trastornos de la personalidad', 'El egocentrismo y la determinación de los objetivos o metas, teniendo en cuenta la obtención de satisfacción personal, es característico del funcionamiento personal del trastorno de la personalidad:', '["Antisocial.", "Límite.", "Narcisista.", "Esquizotípico."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 13, autoevaluación, pregunta 7.'),
('BELLOCH', 'Trastornos de la personalidad', 'Indique en cuál de los TP que se relacionan están principalmente afectados rasgos de las facetas de la afectividad negativa y la desinhibición:', '["Evitativo.", "Límite.", "Antisocial.", "Obsesivo-compulsivo."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 13, autoevaluación, pregunta 8.'),
('BELLOCH', 'Trastornos de la personalidad', 'Indique cuáles de los trastornos de personalidad que se relacionan aparecen en varias secciones o categorías del DSM-5:', '["Límite y narcisista.", "Antisocial y esquizotípico.", "Paranoide y esquizoide.", "Evitativo y obsesivo-compulsivo."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 13, autoevaluación, pregunta 9.'),
('BELLOCH', 'Trastornos de la personalidad', '¿Cuál de las siguientes afirmaciones es correcta con respecto a la evaluación de los TP?', '["Las personas con TP suelen solicitar la ayuda profesional con el objetivo de modificar ciertos aspectos de su personalidad (p. ej., visión de sí mismo, relaciones interpersonales), que interfieren en su calidad de vida y en la relación con los demás.", "Los síntomas que acompañan a los TP son clínicamente distintos a la psicopatología de los demás trastornos mentales.", "El diagnóstico clínico de los TP está libre de la influencia de sesgos culturales y de género, dado que su diagnóstico se basa en criterios clínicos bien establecidos, que minimizan los sesgos del evaluador/a.", "La evaluación requiere recoger información sobre una multitud de contextos y dominios, además de valorar la gravedad del TP en la actualidad."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 13, autoevaluación, pregunta 10.'),
('BELLOCH', 'Trastorno límite de la personalidad', 'En la CIE-11 el patrón límite de la personalidad aparece como:', '["Un trastorno separado de los demás trastornos de la personalidad.", "Un especificador de patrón de personalidad prominente.", "No aparece el patrón límite en la CIE-11.", "Uno de los trastornos graves de la personalidad."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 14, autoevaluación, pregunta 1.'),
('BELLOCH', 'Trastorno límite de la personalidad', 'El trastorno límite de la personalidad en adultos se diagnostica más en:', '["Mujeres.", "Varones.", "No se tienen datos de las diferencias entre sexos.", "No hay diferencias en prevalencia entre sexos."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 14, autoevaluación, pregunta 2.'),
('BELLOCH', 'Trastorno límite de la personalidad', 'Las conductas parasuicidas se pueden definir como:', '["El primer intento grave de suicidio.", "Un intento de suicidio no consumado.", "Un intento de suicidio reiterado (dos o más intentos).", "Infligirse daño físico sin la intención de morir."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 14, autoevaluación, pregunta 3.'),
('BELLOCH', 'Trastorno límite de la personalidad', 'El TPL presenta una alta comorbilidad con:', '["La esquizofrenia.", "Los trastornos alimentarios.", "Los trastornos del neurodesarrollo.", "El trastorno de estrés agudo."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 14, autoevaluación, pregunta 4.'),
('BELLOCH', 'Trastorno límite de la personalidad', 'Específicamente en la adolescencia, al hacer el diagnóstico de TPL hay que tener en cuenta hacer el diagnóstico diferencial con:', '["En la adolescencia no se puede diagnosticar el TPL.", "Los problemas relativos al grupo primario de apoyo.", "Los conflictos de pareja.", "Los problemas de identidad."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 14, autoevaluación, pregunta 5.'),
('BELLOCH', 'Trastorno límite de la personalidad', 'Los principales modelos etiológicos sobre el desarrollo del TPL son:', '["Los modelos interdisciplinares.", "Los modelos de vulnerabilidad biológica e impulsividad.", "Los modelos de desregulación emocional y de la cognición social desadaptativa.", "Los modelos de las cascadas emocionales."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 14, autoevaluación, pregunta 6.'),
('BELLOCH', 'Trastorno límite de la personalidad', 'Señale la respuesta correcta:', '["El ambiente temprano desadaptativo es un factor de riesgo clave en el desarrollo del TPL.", "Los síntomas del TPL preceden a los síntomas de trastornos internalizantes y externalizantes en la adolescencia.", "La desregulación emocional en la infancia representa totalmente la interacción entre experiencias desadaptativas tempranas y el desarrollo del TPL.", "Los estilos de crianza no se asocian con el desarrollo del TPL."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 14, autoevaluación, pregunta 7.'),
('BELLOCH', 'Trastorno límite de la personalidad', 'Señale la respuesta correcta sobre las recomendaciones para la evaluación del TPL:', '["Los modelos categoriales del TPL se basan en el uso de autoinformes para evaluar el TPL.", "El TPL no se puede evaluar de una forma dimensional.", "Las entrevistas clínicas semiestructuradas se recomiendan para diagnosticar el TPL.", "No existen autoinformes válidos para evaluar los síntomas del TPL."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 14, autoevaluación, pregunta 8.'),
('BELLOCH', 'Trastorno límite de la personalidad', 'La terapia basada en la mentalización se enmarca en la perspectiva:', '["Psicodinámica.", "Cognitiva.", "De aceptación y compromiso.", "Cognitivo-comportamental."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 14, autoevaluación, pregunta 9.'),
('BELLOCH', 'Trastorno límite de la personalidad', 'La intervención psicológica con más evidencia para el TPL es:', '["El programa STEPPS.", "La Terapia Centrada en Esquemas.", "La Terapia Basada en la Mentalización.", "La Terapia Dialéctica Comportamental."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 14, autoevaluación, pregunta 10.'),
('BELLOCH', 'Trastorno del espectro autista', '¿Qué trastorno en el DSM-5 ha sido excluido del TEA?', '["Trastorno autista.", "Trastorno desintegrativo infantil.", "Trastorno de Asperger.", "Síndrome de Rett."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 15, autoevaluación, pregunta 1.'),
('BELLOCH', 'Trastorno del espectro autista', 'Un niño con TEA reacciona con una actitud de enfado y disgusto porque una silla de la cocina de su casa está desplazada unos centímetros. ¿A qué se debe que el niño se comporte de esta manera?', '["Falta de control inhibitorio.", "Ceguera mental.", "Falta de empatía.", "Preservar la invariabilidad del medio."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 15, autoevaluación, pregunta 2.'),
('BELLOCH', 'Trastorno del espectro autista', '¿Qué teoría sostiene que las personas afectadas con TEA tienen problemas para integrar la información en un todo y que de forma persistente se centran en los pequeños detalles?', '["Teoría de la mente.", "Teoría de la «coherencia central débil».", "Teoría del déficit en funciones ejecutivas.", "Teoría de la «empatía-sistematización»."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 15, autoevaluación, pregunta 3.'),
('BELLOCH', 'Trastorno del espectro autista', 'Según la teoría empatía-sistematización de Baron-Cohen, la probabilidad y vulnerabilidad al TEA se incrementa cuando hay:', '["Alta empatía y baja sistematización.", "Alta empatía y alta sistematización.", "Baja empatía y alta sistematización.", "Baja empatía y baja sistematización."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 15, autoevaluación, pregunta 4.'),
('BELLOCH', 'Trastorno del espectro autista', '¿Qué consecuencias tienen en el niño con TEA los patrones de comportamientos repetitivos y estereotipados?', '["Interfiere en la responsividad.", "Son una fuente de frustración y malestar.", "Favorecen el aprendizaje de habilidades motoras.", "Favorecen la adquisición de conductas normales."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 15, autoevaluación, pregunta 5.'),
('BELLOCH', 'Trastorno del espectro autista', '¿Cuál es el mejor predictor de la integración y recuperación funcional de los niños con TEA?', '["Un cociente intelectual alto.", "La atención temprana.", "La profesión de la madre.", "La detección precoz."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 15, autoevaluación, pregunta 6.'),
('BELLOCH', 'Trastorno del espectro autista', '¿Qué valor se le concede a la falta del desarrollo del lenguaje en los niños con TEA?', '["El retraso del desarrollo del lenguaje se hace más patente a partir de los cuatro años.", "Es la primera sospecha que tienen los padres de que su hijo tiene algún problema.", "Según el DSM-5 es un síntoma del criterio B del TEA.", "El niño con TEA muestra un adecuado desarrollo del lenguaje en los primeros años."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 15, autoevaluación, pregunta 7.'),
('BELLOCH', 'Trastorno del espectro autista', '¿Qué papel se considera que tiene en el niño con TEA la conducta estereotipada, también denominada conducta autoestimuladora?', '["Las conductas estereotipadas no juegan un papel de especial relevancia en los niños con autismo.", "La mayoría de estos niños emplean la mayor parte de su tiempo en otros comportamientos más satisfactorios para ellos.", "Se considera que las conductas estereotipadas interfieren en la responsividad del niño y en la adquisición de conductas normales.", "Las conductas autolesivas son un ejemplo manifiesto de conductas estereotipadas."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 15, autoevaluación, pregunta 8.'),
('BELLOCH', 'Trastorno del espectro autista', 'En la actualidad el TEA se considera:', '["Un trastorno del neurodesarrollo de origen neurobiológico que se manifiesta de forma precoz.", "Un trastorno del neurodesarrollo caracterizado por problemas de comunicación social sin comportamientos estereotipados.", "Un trastorno del neurodesarrollo que siempre va asociado a discapacidad intelectual.", "Un trastorno del neurodesarrollo de origen neurobiológico cuyos síntomas se manifiestan después de los seis años."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 15, autoevaluación, pregunta 9.'),
('BELLOCH', 'Trastorno del espectro autista', 'La investigación en neurociencias sugiere que la incapacidad de relacionarse y comportarse de manera empática de las personas con TEA está relacionada con:', '["Un menor número y tamaño de las células de Purkinje.", "Una disfunción cerebelosa.", "Las variaciones estructurales de algunos genes.", "Las neuronas espejo."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 15, autoevaluación, pregunta 10.'),
('BELLOCH', 'Trastorno por déficit de atención con hiperactividad', 'Respecto de los criterios de diagnóstico del TDAH (DSM-5), señale la opción correcta:', '["Requieren que algunos de los síntomas se hayan producido antes de los siete años de edad.", "Requieren que los síntomas deben estar presentes hasta el comienzo de la edad adulta.", "Requieren que los síntomas estén presentes bien en la escuela (o el trabajo) o bien en el seno familiar.", "Se ha eliminado el requerimiento (presente en el DSM-IV-TR) de que los síntomas no aparezcan exclusivamente en el transcurso de un trastorno generalizado del desarrollo."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 16, autoevaluación, pregunta 1.'),
('BELLOCH', 'Trastorno por déficit de atención con hiperactividad', 'Los datos epidemiológicos parecen señalar que la cifra de prevalencia de TDAH en la población general está:', '["Por debajo del 5%.", "Entre el 5% y el 10%.", "Por encima del 10%.", "Entre el 10% y el 20%."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 16, autoevaluación, pregunta 2.'),
('BELLOCH', 'Trastorno por déficit de atención con hiperactividad', 'Los primeros síntomas de TDAH en manifestarse, antes de los seis años de edad, suelen ser, con mayor probabilidad:', '["Los de inatención.", "Los de hiperactividad-impulsividad.", "Los agresivos.", "Los emocionales."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 16, autoevaluación, pregunta 3.'),
('BELLOCH', 'Trastorno por déficit de atención con hiperactividad', 'Señale la opción que hace referencia al trastorno menos comórbido en TDAH:', '["Trastorno negativista desafiante.", "Trastorno de conducta (TC).", "Trastorno específico del aprendizaje.", "Trastornos de ansiedad y depresión."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 16, autoevaluación, pregunta 4.'),
('BELLOCH', 'Trastorno por déficit de atención con hiperactividad', 'En lo relativo a los factores epigenéticos que pueden afectar al desarrollo del TDAH:', '["Se ha propuesto la hipótesis catecolaminérgica como principal factor de riesgo.", "Se ha formulado la hipótesis nutricional, encontrándose datos a favor del papel beneficioso de los suplementos de ácidos grasos omega 3 y 6 asociados a mejoras relacionadas con la atención, en los síntomas clínicos de TDAH.", "Se ha demostrado que las pautas de crianza son un factor causal clave en la génesis del TDAH y la gravedad de los síntomas.", "El parto inducido es el factor ambiental con mayor evidencia en relación con el origen del trastorno."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 16, autoevaluación, pregunta 5.'),
('BELLOCH', 'Trastorno por déficit de atención con hiperactividad', 'Según la hipótesis de las catecolaminas en el desarrollo del TDAH:', '["Se producen alteraciones en la neurotransmisión estrechamente vinculadas a las variaciones de tipo genético, principalmente, de los genes que codifican receptores y transportadores de dopamina y noradrenalina.", "Existe un patrón específico de activación simultáneo entre la red neuronal orientada a tareas y la red neuronal por defecto.", "Se ha mostrado un aumento en el metabolismo cerebral regional de la glucosa en el lóbulo frontal.", "Se ha mostrado que una disminución de los niveles de dopamina y serotonina disponibles permite una reducción de los síntomas de impulsividad e hiperactividad."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 16, autoevaluación, pregunta 6.'),
('BELLOCH', 'Trastorno por déficit de atención con hiperactividad', 'Dentro de los factores biológicos asociados a la sintomatología del TDAH se ha identificado:', '["Una disminución de las ondas theta.", "Una ratio elevada de las ondas theta/beta.", "Un incremento de las ondas alfa y beta.", "Una disminución de las ondas alfa y theta."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 16, autoevaluación, pregunta 7.'),
('BELLOCH', 'Trastorno por déficit de atención con hiperactividad', 'El modelo de inhibición conductual y autorregulación de Barkley como teoría explicativa del TDAH:', '["Considera que el déficit en la inhibición de la respuesta es central en el desarrollo de la sintomatología del trastorno.", "Considera que la aversión a la demora es el déficit que afecta de forma principal y jerárquica al resto de las funciones ejecutivas.", "Propone seis funciones ejecutivas que son: activación, concentración, esfuerzo, emoción, memoria y acción.", "Destaca las dificultades en la regulación de los estados energéticos necesarios para satisfacer las demandas de las tareas, produce déficits ejecutivos en el procesamiento de la información."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 16, autoevaluación, pregunta 8.'),
('BELLOCH', 'Trastorno por déficit de atención con hiperactividad', 'En relación a los modelos cognitivos de déficit múltiple formulados como teorías explicativas para el TDAH destacan:', '["El modelo explicativo de Brown, el modelo cognitivo-energético de Sergeant, los modelos de doble y triple vía de Sonuga-Barke y algunos modelos de comorbilidad.", "El modelo de la memoria de trabajo de Rapport, el modelo cognitivo-energético de Sergeant y los modelos de doble y triple vía de Sonuga-Barke.", "El modelo de inhibición conductual y autorregulación de Barkley, el modelo de la memoria de trabajo de Rapport, el modelo cognitivo-energético de Sergeant y los modelos de doble y triple vía de Sonuga-Barke.", "El modelo sobre la cognición social o teoría de la mente (ToM)."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 16, autoevaluación, pregunta 9.'),
('BELLOCH', 'Trastorno por déficit de atención con hiperactividad', 'En el marco de la teoría de la mente (ToM), dentro del estudio del TDAH, se han propuesto distintos procesos o niveles de complejidad que son:', '["Los mecanismos atencionales y los procesos cognitivos básicos implicados en la codificación de estímulos, la búsqueda, el procesamiento central, la decisión y la organización motora de la respuesta.", "El reconocimiento facial de emociones, las creencias de primer y segundo orden, la utilización social del lenguaje y el comportamiento social y la empatía.", "El control inhibitorio de las funciones ejecutivas y mecanismos de recompensa.", "Los mecanismos de supervisión, planificación, monitorización, detección y corrección de los errores."]', 1, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 16, autoevaluación, pregunta 10.'),
('BELLOCH', 'Trastornos neurocognitivos', 'Un hombre de 69 años presenta deterioro cognitivo, que es fluctuante, junto con caídas, alucinaciones visuales y parkinsonismo. ¿Cuál es el diagnóstico más probable?', '["Enfermedad de Alzheimer.", "Demencia por infarto múltiple.", "Demencia con cuerpos de Lewy.", "Demencia por enfermedad de Parkinson."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 17, autoevaluación, pregunta 6.'),
('BELLOCH', 'Trastornos neurocognitivos', 'Un aspecto diferencial que permite establecer el diagnóstico de la demencia incipiente frente a la alteración cognitiva leve es:', '["La presencia de alteraciones funcionales significativas.", "Una alteración más severa en las pruebas de memoria.", "El deterioro neuropsicológico global.", "Todas son correctas."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 17, autoevaluación, pregunta 7.'),
('BELLOCH', 'Trastornos neurocognitivos', '¿En cuál de las siguientes demencias la disfunción ejecutiva se acompaña de un trastorno de conducta severo en fases incipientes?', '["Demencia frontotemporal.", "Demencia tipo Alzheimer.", "Demencia con cuerpos de Lewy.", "Demencia vascular."]', 0, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 17, autoevaluación, pregunta 8.'),
('BELLOCH', 'Trastornos neurocognitivos', 'Con respecto a la EA, es correcto decir que:', '["El primer sistema de memoria afectado es la memoria procedimental.", "El foco inicial del proceso neurodegenerativo es la corteza prefrontal dorsolateral izquierda.", "El deterioro de los recuerdos episódicos suele ser un síntoma temprano muy común.", "El tratamiento farmacológico con acetilcolinesterásicos previene la progresión de la EA."]', 2, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 17, autoevaluación, pregunta 9.'),
('BELLOCH', 'Trastornos neurocognitivos', 'Una evaluación diagnóstica completa de la demencia requiere:', '["Evaluación del estado mental.", "Análisis de sangre y pruebas complementarias.", "Exploración neurológica.", "Todas las anteriores."]', 3, 'Belloch, Sandín y Ramos, Manual de psicopatología, vol. II (4.ª ed.), cap. 17, autoevaluación, pregunta 10.'),
('BELLOCH', 'Historia de la psicopatología', 'Para Hipócrates la enfermedad mental se debía a:', '["Un castigo o maldición divina.", "Causas y procesos naturales, al igual que las enfermedades físicas.", "La ruptura entre el alma irracional y la racional.", "La pobreza y la clase social."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Historia de la psicopatología', '¿Cuál de las siguientes afirmaciones NO fue una de las aportaciones principales del magnetismo?', '["Probar la eficacia del uso de imanes para el tratamiento de los enfermos mentales.", "Plantear la idea de salud como equilibrio.", "Proponer la existencia de la mente no consciente.", "Sentar las bases de algunos principios psicodinámicos, como la trasferencia."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Historia de la psicopatología', 'Señala la afirmación correcta. El tratamiento moral:', '["Se basaba en las leyes del derecho romano, que consideraban la enfermedad mental como un atenuante de los actos delictivos.", "Se basaba en los principios del darwinismo, para explicar el aislamiento social de los enfermos mentales.", "Buscaba modificar la actitud de la sociedad hacia los enfermos mentales y sirvió para reformar las leyes respecto a las instituciones mentales.", "Tenía como misión la protección de los dogmas cristianos y una de sus funciones fue la persecución de la brujería."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Historia de la psicopatología', 'Los modelos de vulnerabilidad y diátesis-estrés tienen sus raíces principales en las teorías:', '["Evolucionistas.", "Fisiológicas.", "Hereditarias.", "Anatómicas."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Historia de la psicopatología', 'La contribución más importante de James McKeen Cattell (1860-1944) a la psicopatología fue:', '["Formular una teoría psicopatológica sobre las neurosis experimentales.", "El énfasis en las aplicaciones prácticas de los test (por ejemplo, selección de personas, indicadores de enfermedad, etc.)", "Desarrollar técnicas terapéuticas basadas en el poder de la palabra y en las relaciones entre paciente-terapeuta.", "Escribir el primer texto de Psicología científica-experimental (“Principios de Psicología Fisiológica”)"]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Historia de la psicopatología', 'Señala cuál de las siguientes afirmaciones es un hito de la historia de la psicopatología del siglo XX:', '["Las aportaciones sobre la herencia, la fisiología y el evolucionismo.", "El surgimiento de la primera reforma psiquiátrica.", "El origen de la frenología de Gall.", "El surgimiento de los primeros sistemas de clasificación de los trastornos mentales."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Historia de la psicopatología', 'Según diversos autores, el fundador de la psicopatología moderna fue:', '["W. Wundt.", "K. Jaspers.", "J.M. Cattell.", "E. Kraepelin."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Historia de la psicopatología', 'La distinción entre psicosis maníaco-depresiva y demencia precoz se la debemos a:', '["Kraepelin.", "Bleuler.", "Schneider.", "Jaspers."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Historia de la psicopatología', 'Los Criterios Feighner eran:', '["Un primer prototipo de sistema de clasificación y diagnóstico que proporciona definiciones de las enfermedades mentales más frecuentes.", "Los criterios diagnósticos de investigación (Research Diagnostic Criteria, RDC)", "Uno de los ejes diagnósticos del DSM-III.", "Los criterios que hacían referencia a los “síntomas de primer orden”."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Historia de la psicopatología', 'El concepto “tipo de reacción” como criterio de organización diagnóstica en el primer DSM se debe a la influencia de:', '["S. Freud.", "K. Jaspers.", "A. Meyer.", "E. Kraepelin."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Modelos en psicopatología', '¿Cuál de los principios que se enumeran es característico de la psicopatología basada en modelos de condicionamiento?', '["El origen de las psicopatologías radica en conflictos que permanecen en el inconsciente.", "Las conductas anormales se producen como consecuencia del aprendizaje de, y la exposición a, estímulos y situaciones específicas.", "La investigación de procesos internos, incluyendo la experiencia subjetiva, es clave para entender las psicopatologías.", "La familia y/o grupo social de referencia son los principales productores de psicopatologías."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Modelos en psicopatología', '¿Cuál de los criterios que se enumeran es más necesario para entender y abordar las psicopatologías?', '["El biológico.", "El estadístico.", "El interpersonal o social.", "Todos los anteriores de forma conjunta."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Modelos en psicopatología', 'Indique cuál de los principios que se enumeran es característico de la psicopatología de orientación cognitiva:', '["El origen de las psicopatologías radica en conflictos que permanecen en el inconsciente.", "Las conductas anormales se producen como consecuencia del aprendizaje de, y la exposición a, estímulos y situaciones específicas.", "La investigación de procesos internos, incluyendo la experiencia subjetiva, es clave para entender las psicopatologías.", "La familia y/o grupo social de referencia son los principales productores de psicopatologías."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Modelos en psicopatología', '“Psicopatológico es todo comportamiento o experiencia mental que se desvía de la normalidad”. Esta afirmación se corresponde bien con el criterio:', '["Médico o biológico.", "Psicodinámico.", "Conductual.", "Estadístico."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Modelos en psicopatología', 'En Psicopatología, el énfasis en el estudio de los procesos y funciones mentales anómalos es característico del modelo:', '["Biomédico.", "Conductual.", "Psicodinámico.", "Cognitivo."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Modelos en psicopatología', 'Cuando un paciente afirma que ha perdido el apetito, está haciendo referencia a un:', '["Un signo.", "Un síntoma.", "Una experiencia subjetiva.", "Un estresor."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Modelos en psicopatología', 'Observamos que un paciente ha perdido peso desde la última vez que le vimos, hace un mes. Cuando indagamos sobre ello nos dice que no está haciendo dieta alguna. La pérdida de peso en este caso es:', '["Un signo.", "Un síntoma.", "Una experiencia subjetiva.", "Un estresor."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Modelos en psicopatología', 'La egodistonía con respecto a un síntoma o trastorno hace referencia a:', '["El malestar intersubjetivo que provocan los síntomas.", "La interferencia que provocan los síntomas en la vida cotidiana.", "Un estado de disonancia o conflicto entre la autoimagen y lo que representa el síntoma para el individuo.", "Una escasa o nula consciencia del problema que puede representar el síntoma o el trastorno."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Modelos en psicopatología', 'Una “variable encubierta” es:', '["Una variable mediacional, no observable directamente.", "Una variable mediacional que se manifiesta y, por tanto, se observa directamente cuando el individuo interactúa con otras personas o realiza una tarea experimental controlada.", "Un estado del organismo que sólo es cuantificable a través de la introspección.", "Una variable que no es cuantificable."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Modelos en psicopatología', 'En las personas, los procesos de condicionamiento se circunscriben o limitan a:', '["Los aspectos más involuntarios y automáticos del comportamiento.", "Los contenidos conscientes y controlados del procesamiento.", "Los elementos voluntarios, aunque no conscientes, del comportamiento.", "Ninguna de las respuestas anteriores describe correctamente los procesos de condicionamiento."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Clasificación y diagnóstico en psicopatología', 'El sistema diagnóstico multiaxial fue eliminado del sistema de diagnóstico y estadística de los trastornos mentales (DSM) por:', '["El DSM-III.", "El DSM-IV.", "El DSM-5.", "No ha sido eliminado."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Clasificación y diagnóstico en psicopatología', 'En el sistema jerárquico de clasificación propuesto por la taxonomía HiTOP, ¿cuál de los siguientes ocupa una posición más general?', '["El subfactor del miedo.", "El espectro somatomorfo.", "Los componentes de síntomas y rasgos desadaptativos.", "El subfactor de distrés."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Clasificación y diagnóstico en psicopatología', 'El DSM-5 aplica criterios de clasificación y diagnóstico fundamentalmente de tipo:', '["Circumplejo.", "Multidimensional.", "Jerárquico.", "Politético."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Clasificación y diagnóstico en psicopatología', 'Una de las grandes aportaciones en 1948 de la 6.ª edición (CIE-6) a la clasificación de la conducta anormal fue:', '["Introducir el sistema multiaxial.", "Constituir los códigos de diagnóstico internacionales.", "Establecer la correspondencia diagnóstica con el sistema DSM.", "Incluir un capítulo para la clasificación de los trastornos mentales."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Clasificación y diagnóstico en psicopatología', 'En relación con el enfoque transdiagnóstico cabría afirmar lo siguiente:', '["Los constructos transdiagnósticos deben relacionarse etiológicamente con los trastornos.", "Un constructo que se relaciona con múltiples trastornos es por definición un constructo transdiagnóstico.", "El transdiagnóstico es un enfoque dimensional incompatible con las clasificaciones categoriales.", "Una terapia es transdiagnóstica por el hecho de abordar simultáneamente múltiples trastornos."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Clasificación y diagnóstico en psicopatología', 'Indique cuál de los siguientes sistemas de clasificación posee una mayor fundamentación en procesos neurofisiológicos:', '["El sistema dimensional RDoC.", "El sistema categorial DSM-III.", "El sistema dimensional HiTOP.", "La última edición del DSM (DSM-5)"]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Clasificación y diagnóstico en psicopatología', 'Indique cuál de los siguientes grupos generales (clases) de trastornos mentales está incluido en la CIE-11 pero no en el DSM-5:', '["Trastornos parafílicos.", "Trastornos facticios.", "Trastornos del neurodesarrollo.", "Trastornos asociados al estrés o estresores."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Clasificación y diagnóstico en psicopatología', 'Para la construcción de los espectros del DSM-5 se utilizaron varios criterios externos de validación. Por favor, señale cuál de los que se indican a continuación no corresponde a tales criterios:', '["Nivel de gravedad de la enfermedad.", "Similitud de síntomas.", "Factores de riesgo genético.", "Respuesta al tratamiento."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Clasificación y diagnóstico en psicopatología', 'Uno de los siguientes tipos de trastornos no es contemplado como tipo de trastornos mentales en la CIE-11, a pesar de ser considerado como tal en la tradición de la clasificación psiquiátrica, incluido el DSM-5. ¿De qué trastornos se trata?', '["Trastornos disociativos.", "Trastornos neurocognitivos.", "Trastornos del sueño-vigilia.", "TEPT."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Clasificación y diagnóstico en psicopatología', 'Un nuevo tipo de trastorno descrito en la CIE-11 y no en el DSM-5 es:', '["El trastorno de disforia de género.", "El trastorno de estrés postraumático complejo.", "La catatonía.", "Los trastornos del control de impulsos."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la atención y la conciencia', 'La hiperproxesia se caracteriza por:', '["La persona presenta una capacidad disminuida para enfocar, concentrarse u orientarse hacia un objeto.", "Una focalización excesiva y transitoria de la atención sobre un estímulo, aspecto, tema o vivencia.", "Reducción máxima de la disposición atencional.", "Falta de atención hacia el entorno a pesar de mantener conservada la capacidad atencional."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la atención y la conciencia', 'La tarea Stroop emocional sirve para evaluar:', '["El mantenimiento de la atención mientras se está en un estado emocional.", "La presencia de sesgos atencionales hacia la información emocional.", "Dónde fija la atención visual la persona y durante cuánto tiempo en una tarea emocional.", "La atención voluntaria e involuntaria ante información multisensorial."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la atención y la conciencia', 'La hipervigilancia presente en los trastornos de ansiedad por la salud, trastorno de estrés postraumático o dolor crónico hace referencia a:', '["Un estado de alta receptividad o hipersensibilidad, en el que la persona trata de buscar o rastrear señales amenazantes (internas o externas)", "Una atención inestable y superficial, en la que se atiende a muchos estímulos y durante poco tiempo.", "Una gran concentración sobre alguna cuestión concreta (generalmente preocupaciones sobre algún tipo de pensamiento), que a su vez lleva a “desatender” al resto de los estímulos y a no responder a las demandas ambientales.", "Una incapacidad para distinguir unos estímulos de otros, que se acompaña de un escaso rendimiento y abundancia de errores en el test de ejecución continua (CPT)"]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la atención y la conciencia', '¿En qué trastorno se suele presentar la totalidad de las siguientes alteraciones atencionales: Dificultades para identificar y dirigir la atención hacia estímulos relevantes (por ejemplo, atención selectiva), elevada distraibilidad, dificultad para mantenerse vigilante para detectar estímulos específicos (déficits de vigilancia) y dificultades para mantener la concentración?', '["Depresión.", "Esquizofrenia.", "Dolor crónico.", "Ansiedad generalizada."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la atención y la conciencia', '¿Qué alteración atencional se considera un proceso transdiagnóstico presente en diversos trastornos mentales?', '["La distraibilidad o inestabilidad de la atención hacia diferentes estímulos.", "El sesgo hacia los estímulos (externos o internos) que constituyen preocupaciones relevantes.", "El sesgo relacionado con la dificultad para desatender o “desengancharse” de la información negativa y atender a la información positiva.", "La incapacidad para concentrarse o fijar la atención sobre ciertos estímulos, objetos o situaciones."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la atención y la conciencia', 'En el estupor de origen neurológico, la persona (señala la alternativa incorrecta):', '["Conserva sólo las funciones vegetativas.", "Sólo es capaz de alcanzar un estado transitorio de vigilia mediante estimulación muy intensa.", "Puede presentar actividad motora estereotipada.", "No es capaz de realizar ningún tipo de conducta intencional."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la atención y la conciencia', 'El delirium describe:', '["La presencia de un conjunto de delirios sistematizados en torno a un tema coherente.", "Una alteración cuantitativa de la conciencia en donde la conciencia de la persona está exclusivamente focalizada en los estímulos que la rodean, asociado a una falta de capacidad para cambiar el foco de la atención.", "Un síndrome cuya característica esencial es una alteración de la atención y la conciencia que se acompaña de un deterioro en el funcionamiento de los procesos cognitivos.", "Un estado alterado de conciencia que aparece como consecuencia de la epilepsia, generalmente, en los ataques epilépticos del lóbulo temporal."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la atención y la conciencia', 'En la confusión de los límites del yo, la persona:', '["Presenta la convicción delirante acerca de que sus propios pensamientos son captados por un agente externo a él.", "Experimenta una sensación subjetiva de irrealidad respecto al mundo que le rodea.", "Presenta la convicción delirante de que sus acciones están manipuladas y dirigidas por un ente superior.", "Es incapaz de experimentarse a sí mismo como una entidad diferenciada del entorno."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la atención y la conciencia', 'Las experiencias disociativas:', '["Tienen un valor adaptativo.", "Son experiencias patológicas puesto que implican la pérdida de conciencia de la cualidad personal de las propias acciones del sujeto.", "Se dan sólo en contextos de cuadros psicopatológicos que conllevan la pérdida de la identidad personal.", "Sólo se dan en los trastornos disociativos."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la atención y la conciencia', 'En la despersonalización, la persona:', '["Pierde la conciencia de su identidad personal.", "Experimenta una sensación subjetiva de extrañeza e irrealidad respecto a sí mismo.", "Presenta amnesia para lo ocurrido durante el episodio.", "Es incapaz de reconocer la cualidad personal de sus pensamientos, sentimientos y acciones."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la percepción y la imaginación', 'Las hiperestesias e hipoestesias son:', '["Anomalías en la percepción de la intensidad de los estímulos que causan dolor, por ejemplo, percepción exagerada o muy escasa de la intensidad del dolor.", "Anomalías en la percepción de la intensidad de los estímulos, por ejemplo, percibir los estímulos con mayor o menor intensidad de lo esperable.", "Anomalías en la percepción del tamaño o la forma, por ejemplo, percibir los objetos reales a escala reducida o aumentada, respectivamente.", "Modalidades de las ilusiones, por ejemplo, “ver caras” dibujadas en las nubes o en las llamas que surgen en una chimenea."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la percepción y la imaginación', 'Las imágenes eidéticas son:', '["Un tipo especial de imagen mnésica, que consiste en representaciones exactas de impresiones sensoriales que quedan “fijadas” en la mente de la persona.", "Imágenes que aparecen en estados de semiinconsciencia, entre la vigilia y el sueño.", "Un tipo de imágenes parásitas que se presentan de forma autónoma e involuntaria.", "Un tipo de imágenes consecutivas o postimágenes, que se producen tras un exceso de estimulación sensorial y se mantienen unos pocos segundos después."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la percepción y la imaginación', 'Las alucinaciones que dan órdenes, se denominan:', '["Eco del pensamiento o eco de la lectura.", "Acoasmas.", "Alucinaciones auditivas imperativas.", "Voces que comentan en tercera persona."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la percepción y la imaginación', 'Cuando una persona explica que “las venas se le salen, se le enrollan y se hacen una burbuja en el cuerpo”, puede estar experimentando:', '["Una alucinación somática o visceral.", "Una alucinación táctil o háptica.", "Una alucinación visual.", "Una imagen alucinoide."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la percepción y la imaginación', 'Las alucinaciones más frecuentes en la esquizofrenia y los trastornos del espectro psicótico son:', '["Olfativas.", "Visuales.", "Somáticas.", "Auditivas."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la percepción y la imaginación', 'La característica definitoria del Síndrome de Charles Bonnet es:', '["La experimentación de alucinaciones liliputienses.", "La experimentación del fenómeno del “miembro fantasma” después de una amputación.", "La experimentación de alucinaciones de viudedad.", "La presencia de alucinaciones no es una característica definitoria de este síndrome."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la percepción y la imaginación', 'En relación con el trauma y las alucinaciones, los estudios señalan:', '["El abuso sexual infantil se ha relacionado con la presencia de delirios, pero no con la frecuencia de las alucinaciones.", "Las víctimas de abusos sexuales y físicos en la infancia presentan un porcentaje mayor de alucinaciones que aquellas que han sufrido un solo tipo de abuso.", "No se han observado asociaciones significativas entre experimentar voces que comentan y el abuso en la infancia.", "Las personas abusadas en la infancia (abuso sexual y físico) tienen las mismas probabilidades de experimentar síntomas de contenidos sexuales, que aquellas no abusadas."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la percepción y la imaginación', 'Señale cuál de las siguientes afirmaciones es correcta con respecto a las creencias asociadas a las voces y el malestar:', '["Los estudios de tratamiento han mostrado que, tras la intervención, se reducen las creencias de malevolencia y los índices de malestar (ansiedad, depresión)", "No hay datos de evidencia que avalen la relación entre las creencias asociadas a las voces y el malestar.", "La creencia de supremacía de las voces mantiene relaciones positivas con los niveles de malestar, estado de ánimo deprimido y ansiedad.", "Se ha demostrado que las creencias de benevolencia son predictores independientes de malestar asociado a las voces."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la percepción y la imaginación', 'En relación a la escucha de voces en la población con y sin diagnóstico clínico, los resultados muestran que:', '["Los escuchadores de voces sin diagnóstico experimentan menos voces con contenidos negativos que los escuchadores con diagnóstico.", "Los escuchadores de voces sin diagnóstico son personas con un trastorno psicótico, que no ha sido diagnosticado.", "Los escuchadores con y sin diagnóstico experimentan alucinaciones auditivas de forma análoga, tanto en sus cualidades perceptivas, contenidos y respuestas asociadas.", "La escucha de voces parece ser una experiencia discontinua, que se adapta mejor a modelos diagnósticos categoriales que a modelos dimensionales."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la percepción y la imaginación', 'Señale la afirmación incorrecta. En relación con las adaptaciones de la TCC para el tratamiento de las personas con psicosis, es necesario:', '["Realizar un período de evaluación más extendido en el tiempo.", "Supervisar y controlar el nivel de activación emocional.", "Ajustar las expectativas de cambio teniendo en cuenta la cronicidad, la gravedad y los posibles déficits subyacentes.", "Establecer una alianza terapéutica igual que se hace con cualquier otro grupo de pacientes."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la memoria', 'Se dice que un paciente es amnésico “puro” si:', '["Además de amnesia retrógrada se produce un cierto grado de amnesia anterógrada, más grave en las horas posteriores a la lesión, pero que va desapareciendo con el tiempo.", "Tiene amnesia anterógrada, que se puede acompañar de amnesia retrógrada, pero conserva intactas su capacidad intelectual y las destrezas adquiridas antes de la lesión, y no presenta problemas de lenguaje, perceptivos ni atencionales.", "Presenta únicamente amnesia retrógrada, pero la anterógrada funciona correctamente.", "Presenta únicamente amnesia anterógrada y, como consecuencia, su capacidad intelectual está ligeramente disminuida."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la memoria', 'La modalidad de amnesia más típica después de recibir terapia electroconvulsiva es:', '["Anterógrada.", "Explícita.", "Implícita.", "Retrógrada."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la memoria', 'La amnesia funcional:', '["Se produce como consecuencia de un TCE o lesión cerebral.", "Afecta a, y engloba, todos los conocimientos adquiridos en el pasado.", "Es una amnesia episódica explícita.", "Es una amnesia semántica."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la memoria', 'La criptoamnesia es un ejemplo característico de un funcionamiento anómalo de:', '["El recuerdo.", "El reconocimiento.", "La represión.", "La memoria a largo plazo."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la memoria', '¿Qué alteración padece un individuo que cree que una persona importante en su vida (por ejemplo, su hija) no es realmente ella, que su cuerpo está siendo ocupado por un impostor, aunque reconoce que tiene la misma apariencia física?', '["Síndrome de Capgras o Delirio de Sosías.", "Alucinación visual extracampina.", "Alucinación negativa.", "Criptoamnesia."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la memoria', 'Con los ojos cerrados toca un objeto y lo describe como un trozo de alambre doblado con una punta afilada en uno de los extremos, sin embargo, no reconoce que es un imperdible. Esta persona puede presentar una:', '["Agnosia visual.", "Alucinación táctil.", "Agnosia táctil.", "Paramnesia."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la memoria', 'Los trastornos disociativos se diferencian de los síndromes mentales orgánicos en que en los primeros se produce:', '["Alteraciones en la memoria sensorial, pero no en la memoria de trabajo.", "Alteraciones en las fases de adquisición y codificación de la memoria.", "Pérdidas de memoria circunscritas al material personalmente relevante.", "Alteraciones en las funciones intelectuales y cognoscitivas."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la memoria', 'La amnesia retrógrada consiste en:', '["Incapacidad para recordar información semántica, aunque se conserva la memoria episódica, después de haber sufrido un traumatismo.", "Incapacidad para recordar lo sucedido durante algún período circunscrito del pasado, como consecuencia de un trauma emocional.", "Incapacidad para fijar nuevos conocimientos después de un trauma craneal.", "Incapacidad para recordar el pasado autobiográfico, como consecuencia del traumatismo."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la memoria', 'Se está evaluando el deterioro cognitivo en un paciente con TCE. Al realizar un test de razonamiento no verbal, cada vez que se pasa una página hay que repetir de nuevo las instrucciones al paciente, ya que le parece que cada vez se enfrenta a una situación completamente nueva. Este hecho indica la presencia de:', '["Jamais vu.", "Amnesia disociativa.", "Amnesia retrógrada.", "Amnesia anterógrada."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del pensamiento', 'El fracaso en seguir adecuadamente la cadena de ideas y pensamientos hasta su conclusión, se denomina según la clasificación de Andreasen:', '["Circunstancialidad.", "Bloqueo.", "Pérdida de meta.", "Descarrilamiento."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del pensamiento', 'Singer y Wynne propusieron unas categorías de comunicación desviada cuyo objetivo es, en esencia:', '["Analizar las dificultades del lenguaje expresivo de los pacientes esquizofrénicos.", "Categorizar y evaluar las anomalías y trastornos en el lenguaje y/o discurso individual.", "Proporcionar a los clínicos una escala para la evaluación de las alteraciones del lenguaje que se producen en el contexto de la entrevista con los pacientes.", "Caracterizar las dificultades para compartir un foco de atención y transmitir un mensaje con significado compartido."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del pensamiento', '¿Qué alteración padece una persona que cree que sus pensamientos no son suyos, sino que se los ha introducido en la mente una fuerza exterior e irresistible?', '["Eco del pensamiento.", "Fuga de ideas.", "Idea delirante de control.", "Idea delirante de negación."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del pensamiento', '¿Cuál de las siguientes características es típica de una idea delirante?', '["El individuo persevera una y otra vez con un pensamiento circular e ilógico.", "El balance entre las evidencias a favor y en contra de lo que piensa es tal que cualquier otra persona no daría crédito a lo que el individuo considera como evidencias a favor.", "La persona dice que lo que está pensando es absurdo, pero no puede dejar de pensar en ello.", "El individuo cree que lo que piensa puede ser compartido por los demás y por ello hace esfuerzos por convencer a los otros de sus ideas."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del pensamiento', '¿Qué alteración padece un individuo que cree que una persona importante en su vida (por ejemplo, su hija) no es realmente ella, que su cuerpo está siendo ocupado por un impostor, aunque reconoce que tiene la misma apariencia física?', '["Síndrome de Capgras o delirio de Sosías.", "Alucinación visual extracampina.", "Alucinación negativa.", "Delirio de persecución."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del pensamiento', 'El planteamiento de B. Maher acerca de los delirios se basa en el supuesto de que estos trastornos:', '["Representan el punto más álgido de lo que significa el pensamiento ilógico e incoherente.", "Se producen porque el sujeto comete errores de atribución, tales como realizar atribuciones consistentemente externas, globales y estables para acontecimientos negativos.", "Representan la expresión de deseos y fantasías premórbidas del individuo.", "Surgen como un intento que realiza el paciente de explicarse una experiencia anómala previa, que normalmente consiste en una alteración perceptiva."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del pensamiento', 'Indica cuál de las siguientes observaciones no avala el planteamiento de B. Maher sobre los delirios:', '["La gente lega no está orientada a los datos: prefiere explicaciones “mágicas” o misteriosas sobre lo que sucede y no entiende.", "El hecho de que para explicar una experiencia anómala se desarrolle una explicación aún más anómala.", "Los delirantes no presentan deterioro en la capacidad de razonamiento lógico.", "Los delirios son muy comunes: aparecen en situaciones y enfermedades de naturaleza y causas muy diversas."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del pensamiento', 'Indica a qué alteración hace referencia la siguiente definición: tendencia a tomar una decisión sin buscar evidencias que la apoyen:', '["Creencia disfuncional de intolerancia a la incertidumbre.", "Sesgo cognitivo de salto a las conclusiones.", "Sesgo cognitivo contra la evidencia desconfirmatoria.", "Estilo atribucional interno."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del pensamiento', 'El planteamiento de Freeman acerca de los delirios de persecución mantiene que:', '["Surgen como un intento de la persona por aumentar su autoestima haciendo atribuciones externas a los sucesos negativos que le ocurren.", "Son la expresión de las fantasías y los deseos premórbidos del individuo.", "Son la expresión del sí-mismo del paciente (“bad me”), que es tan negativo que la persona piensa que merece ser castigada.", "Se mantienen por la interacción de una serie de mecanismos, entre otros las preocupaciones, creencias negativas sobre uno mismo y los sesgos de razonamiento."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del lenguaje', 'Según el DSM-5, el mutismo selectivo es un trastorno de:', '["Ansiedad.", "Lenguaje expresivo.", "Estrés postraumático.", "Discapacidad intelectual."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del lenguaje', '¿Cómo se denomina el trastorno de un niño de 5 años, sin discapacidad intelectual ni déficits sensoriales, neurológicos y sociales remarcables, que cuando habla espontáneamente no es capaz de reproducir los sonidos y al que apenas se entiende lo que dice?', '["Mutismo selectivo.", "Disartria.", "Dislalia fonética.", "Trastorno fonológico."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del lenguaje', '¿En qué síndrome afásico es frecuente el agramatismo?', '["Afasia de Broca.", "Afasia de Wernicke.", "Afasia sensorial-transcortical.", "Afasia anómica-amnésica."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del lenguaje', '¿Cuál es el déficit lingüístico más importante en los niños con trastorno del espectro autista?', '["Las dificultades en procesos atencionales.", "Las dificultades en memoria auditiva.", "La falta de desarrollo de la pragmática del lenguaje.", "La falta de capacidad de metarrepresentación."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del lenguaje', '¿Cuál de estos trastornos no se considera un trastorno del neurodesarrollo?', '["Trastorno del Espectro Autista.", "Mutismo selectivo.", "TDAH.", "Trastorno específico del lenguaje."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del lenguaje', 'En relación al lenguaje de los niños con TEA, señala la respuesta falsa:', '["El lenguaje de los niños con TEA no sólo está retrasado, sino también alterado.", "Los componentes fonológicos y semánticos del lenguaje autista se ajustan a pautas de adquisición de los niños neurotípicos. Por el contrario, los componentes sintácticos y pragmáticos presentan pautas de desviación severas.", "Los niños con TEA utilizan más el lenguaje de forma instrumental que comunicacional.", "Algunas de las características del lenguaje autista son: mutismo, escasez de vocabulario, dificultades articulatorias, empleo de negación como “protección mágica”."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del lenguaje', '¿Cómo se llama a la capacidad de un hablante para ajustar su discurso a la situación en la que se encuentra?', '["Coherencia comunicativa.", "Complacencia comunicativa.", "Cohesión comunicativa.", "Competencia comunicativa."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del lenguaje', '¿A qué síndrome afásico corresponden las siguientes características?: no aparecen trastornos articulatorios, el habla está reducida, la comprensión auditiva está dentro de lo normal, la fluidez es normal en la repetición y al nombrar objetos, pero se reduce en las emisiones espontáneas, presenta:', '["Afasia de Broca.", "Afasia motora transcortical.", "Afasia sensorial transcortical.", "Afasia de conducción."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del lenguaje', '¿Cómo se denomina el patrón del habla acelerado, caracterizado por la producción de oraciones, cuyas palabras son elegidas fundamentalmente por su afinidad o parentesco fonológico (rimas, asonancias, juegos de palabras, etc.)?', '["Tangencialidad.", "Disgregación.", "Glosomanía.", "Descarrilamiento."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología del lenguaje', '¿Cuál de las siguientes respuestas aparece en personas con esquizofrenia?', '["Dificultades de denominación y disartria.", "Buena capacidad de comprensión para seguir el curso de una idea o un tema.", "Pobreza del lenguaje y neologismos.", "Discurso lógico y coherente."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la afectividad', 'El término “estado de ánimo” generalmente se utiliza en lenguaje psicológico para describir:', '["Un concepto amplio que incluye emociones, sentimientos e impulsos motivacionales.", "La experiencia subjetiva de la emoción.", "Una expresión afectiva breve e intensa que suele estar asociada a una causa identificable y/o objeto de referencia.", "Un estado emocional persistente y generalizado que proporciona información sobre nuestro propio estado interno."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la afectividad', 'La pérdida o disminución de la capacidad de disfrute se denomina:', '["Hipotimia.", "Rigidez afectiva.", "Anhedonia.", "Paratimia."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la afectividad', 'La incapacidad para identificar o reconocer las propias emociones se denomina:', '["Incontinencia afectiva.", "Ambivalencia afectiva.", "Afecto discordante.", "Alexitimia."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la afectividad', '¿Cuál de las siguientes estrategias de RE se consideraría que está focalizada en los antecedentes?', '["Supresión.", "Rumiación.", "Revaloración.", "Preocupación."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la afectividad', '¿Cuál de los siguientes trastornos se caracteriza por un problema de “desregulación emocional persistente”?', '["TEPT.", "Trastorno de pánico.", "Depresión.", "TLP."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la afectividad', 'Según el modelo de regulación de Gross, ¿en cuál de las siguientes etapas se decide qué estrategia utilizar?', '["Identificación.", "Selección.", "Atención.", "Implementación."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la afectividad', '¿Cuál de los siguientes mecanismos de RE se consideraría una habilidad de RE?', '["La supresión emocional.", "La revaloración positiva.", "La capacidad para tolerar emociones negativas.", "La rumiación."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la afectividad', 'La flexibilidad en la regulación emocional se define como:', '["El proceso que utilizamos para influir en las emociones y alterar sus trayectorias.", "Sincronía entre las estrategias de regulación emocional utilizadas y los cambios que se produzcan en el contexto.", "La selección de estrategias de regulación emocional.", "Los cambios en la selección y modificación de la situación emocional."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la afectividad', 'El problema fundamental en la fase de identificación en el proceso de regulación emocional es:', '["La selección de estrategias adaptativas.", "La mala utilización de tácticas de regulación emocional específicas.", "La falta de flexibilidad para adecuarse al contexto y modificar las estrategias de regulación emocionales.", "Las dificultades en la conciencia emocional."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la afectividad', '¿Cuál de las siguientes estrategias de RE es frecuentemente utilizada en depresión?', '["La supresión.", "La rumiación.", "La resignación.", "La reevaluación."]', 1, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la psicomotricidad', 'A la pérdida súbita y reversible del tono muscular durante la vigilia sin alteración del nivel de conciencia se le denomina:', '["Acinesia.", "Parálisis.", "Cataplejía.", "Estupor."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la psicomotricidad', 'La obstrucción se caracteriza por:', '["El bloqueo de una actividad motora.", "La pérdida de movimiento o la dificultad para iniciarlo.", "Un estado alterado de conciencia.", "La incapacidad para mover alguna parte del cuerpo como consecuencia de una lesión cerebral."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la psicomotricidad', 'A la incapacidad para cambiar de tarea o movimiento se le denomina:', '["Negativismo.", "Obediencia automática.", "Perseveración.", "Catalepsia."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la psicomotricidad', 'A la expresión exagerada de la mímica facial o de los gestos al hablar se le conoce como:', '["Hipermimia.", "Hipomimia.", "Amimia.", "Dismimia."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la psicomotricidad', '¿Cuál de las siguientes alteraciones de la actividad motora excesiva se define como un estado en el que la persona realiza un gran número de acciones con un objetivo aparente en un breve período de tiempo o simultáneamente?', '["Hipercinesia.", "Agitación.", "Inquietud.", "Acatisia."]', 0, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la psicomotricidad', '¿Qué tipo de temblor estamos evaluando si le pedimos a la persona que trate de tocarse la punta de la nariz con el dedo?', '["Postural.", "Reposo.", "Intencional.", "Parkinsonismo."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la psicomotricidad', '¿Cuál de los siguientes movimientos está considerado como involuntario, pero puede lograr suprimirse por un tiempo limitado?', '["Inquietud.", "Distonía.", "Tics.", "Compulsiones."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la psicomotricidad', 'Juan tiene ansiedad social, únicamente sale a la calle acompañado de su pareja o su madre. Se trata de una:', '["Compulsión.", "Manierismo.", "Búsqueda de reaseguro.", "Conducta de seguridad."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la psicomotricidad', 'En respuesta a la obsesión de “¿Mi novia me es infiel?”, la persona pregunta repetidamente a un familiar próximo si piensa que su novia le es infiel. Se trata de una:', '["Compulsión.", "Manierismo.", "Búsqueda de reaseguro.", "Delirio de celotipia."]', 2, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).'),
('BELLOCH', 'Psicopatología de la psicomotricidad', 'En respuesta a una intrusión de hacer daño a alguien (“que se muera Manolito”), se genera un pensamiento positivo u opuesto (“Manolito es una buena persona que debe vivir”) con la intención de eliminar el negativo. Se trata de un/a:', '["Compulsión.", "Búsqueda de reaseguro.", "Manierismo.", "Neutralización."]', 3, 'Pregunta de repaso de CEDE sobre Belloch, Sandín y Ramos (2020), Manual de psicopatología, vol. I (3.ª ed.).')
) as v(curso, tema, pregunta, opciones, correcta, explicacion)
where not exists (
  select 1 from public.preguntas p
  where p.curso = v.curso and p.pregunta = v.pregunta and p.opciones = v.opciones::jsonb
);
